(function(A){Object.assign(A.D,{"G682":{"l":"Ἀπφία","o":1,"ar":"<f><o>Ἀπφία</o>، <g>-ας, ἡ</g>،</f> <s><b>أبفية</b>: <r v=\"Phlm.1.2\"></r>.†</s>","en":"<f><o>Ἀπφία</o>, <g>-ας, ἡ</g>,</f> <s><b>Apphia</b>: <r v=\"Phlm.1.2\"></r> (MM, s.v.).†</s>"},"G661":{"l":"ἀποτίνω","o":1,"ar":"<f><o>ἀπο-τίνω</o> (أو <g>-τίω</g>)،</f> <s><b>وفّى</b>، <b>ردّ، عوّض</b>: <r v=\"Phlm.1.19\"></r>.†</s>","en":"<f><o>ἀπο-τίνω</o> (or <g>-τίω</g>),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7999\">שׂלם</h> pi.;]</e> </et> <s><b>to pay off</b>, <b>repay</b>: <r v=\"Phlm.1.19\"></r> (MM, s.v.).†</s>"},"G686":{"l":"ἄρα","o":158,"ar":"<f><o>ἄρα</o>،</f> أداة استنتاج، تعبّر عن استنتاج أكثر ذاتيةً أو أقل رسميةً من <x><g>οὖν</g></x>، <s><b>إذًا</b>: أصلاً، الكلمة الثانية في الجملة، <r v=\"Rom.7.21\"></r> <r v=\"Rom.8.1\"></r>، <r v=\"Gal.3.7\"></r>؛ <g>ἐπεὶ ἄρα</g>، <r v=\"1Cor.7.14\"></r> (مع كلمة أخرى بينهما) <r v=\"1Cor.5.10\"></r>؛ كالكلمة الأولى، <r v=\"Luke.11.48\"></r>، <r v=\"Acts.11.18\"></r>، <r v=\"Rom.10.17\"></r>، <r v=\"1Cor.15.18\"></r>، <r v=\"2Cor.5.15\"></r> <r v=\"2Cor.7.12\"></r>، <r v=\"Heb.4.9\"></r>؛ وهكذا أصلاً في جواب الشرط بعد فعل شرط مع <g>εἰ</g>، <r v=\"Matt.12.28\"></r>، <r v=\"Luke.11.20\"></r>، <r v=\"Gal.2.21\"></r> <r v=\"Gal.3.29\"></r> <r v=\"Gal.5.11\"></r>، <r v=\"Heb.12.8\"></r> (<g>κενὸν ἄρα</g>)، <r v=\"1Cor.15.14\"></r>؛ وكثيرًا في الاستفهام المباشر وغير المباشر، <g>τίς</g> (<g>τί</g>) <g>ἄρα</g>، <r v=\"Matt.18.1\"></r> <r v=\"Matt.19.25\"></r>، <r v=\"Matt.19.27\"></r> <r v=\"Matt.24.45\"></r>، <r v=\"Mark.4.41\"></r>، <r v=\"Luke.1.66\"></r> <r v=\"Luke.8.25\"></r> <r v=\"Luke.12.42\"></r> <r v=\"Luke.22.23\"></r>، <r v=\"Acts.12.18\"></r>؛ <g>εἰ ἄρα</g>، <r v=\"Mark.11.13\"></r>، <r v=\"Acts.8.22\"></r>؛ <g>εἴπερ ἄρα</g>، <r v=\"1Cor.15.15\"></r>؛ <g>οὐκ ἄρα</g>، <r v=\"Acts.21.38\"></r>؛ <g>μήτι ἄρα</g>، <r v=\"2Cor.1.17\"></r>؛ وفي صيغ مقوّاة، <g>ἄρα γε</g>، <g>ἄραγε</g>، <r v=\"Matt.7.20\"></r> <r v=\"Matt.17.26\"></r>، <r v=\"Acts.17.27\"></r>، وأكثر شيوعًا <g>ἄρα οὖν</g> (رسائل بولس)، <b>فإذًا</b>، <r v=\"Rom.5.18\"></r> <r v=\"Rom.7.3\"></r>، <r v=\"Rom.7.25\"></r> <r v=\"Rom.8.12\"></r> <r v=\"Rom.9.16\"></r>، <r v=\"Rom.9.18\"></r> <r v=\"Rom.14.12\"></r>، <r v=\"Rom.14.19\"></r>، <r v=\"Gal.6.10\"></r>، <r v=\"Eph.2.19\"></r>، <r v=\"1Thess.5.6\"></r>، <r v=\"2Thess.2.15\"></r>.†</s>","en":"<f><o>ἄρα</o>,</f> illative particle, expressing a more subjective or informal inference than <x><g>οὖν</g></x>, <s><b>then</b>: prop. (as in cl.), the second word in the sentence, <r v=\"Rom.7.21\"></r> <r v=\"Rom.8.1\"></r>, <r v=\"Gal.3.7\"></r>; <g>ἐπεὶ ἄρα</g>, <r v=\"1Cor.7.14\"></r> (with another word between) <r v=\"1Cor.5.10\"></r>; as the first word, <r v=\"Luke.11.48\"></r>, <r v=\"Acts.11.18\"></r>, <r v=\"Rom.10.17\"></r>, <r v=\"1Cor.15.18\"></r>, <r v=\"2Cor.5.15\"></r> <r v=\"2Cor.7.12\"></r>, <r v=\"Heb.4.9\"></r>; so prop. in apodosis after protasis with <g>εἰ</g>, <r v=\"Matt.12.28\"></r>, <r v=\"Luke.11.20\"></r>, <r v=\"Gal.2.21\"></r> <r v=\"Gal.3.29\"></r> <r v=\"Gal.5.11\"></r>, <r v=\"Heb.12.8\"></r> (<g>κενὸν ἄρα</g>), <r v=\"1Cor.15.14\"></r>; often in interrogations, direct and indirect, <g>τίς</g> (<g>τί</g>) <g>ἄρα</g>, <r v=\"Matt.18.1\"></r> <r v=\"Matt.19.25\"></r>, <r v=\"Matt.19.27\"></r> <r v=\"Matt.24.45\"></r>, <r v=\"Mark.4.41\"></r>, <r v=\"Luke.1.66\"></r> <r v=\"Luke.8.25\"></r> <r v=\"Luke.12.42\"></r> <r v=\"Luke.22.23\"></r>, <r v=\"Acts.12.18\"></r>; <g>εἰ ἄρα</g>, <r v=\"Mark.11.13\"></r>, <r v=\"Acts.8.22\"></r>; <g>εἴπερ ἄρα</g>, <r v=\"1Cor.15.15\"></r>; <g>οὐκ ἄρα</g>, <r v=\"Acts.21.38\"></r>; <g>μήτι ἄρα</g>, <r v=\"2Cor.1.17\"></r>; in strengthened forms, <g>ἄρα γε</g>, <g>ἄραγε</g>, <r v=\"Matt.7.20\"></r> <r v=\"Matt.17.26\"></r>, <r v=\"Acts.17.27\"></r>, and more freq. <g>ἄρα οὖν</g> (Epp. Paul.), <b>so then</b>, <r v=\"Rom.5.18\"></r> <r v=\"Rom.7.3\"></r>, <r v=\"Rom.7.25\"></r> <r v=\"Rom.8.12\"></r> <r v=\"Rom.9.16\"></r>, <r v=\"Rom.9.18\"></r> <r v=\"Rom.14.12\"></r>, <r v=\"Rom.14.19\"></r>, <r v=\"Gal.6.10\"></r>, <r v=\"Eph.2.19\"></r>, <r v=\"1Thess.5.6\"></r>, <r v=\"2Thess.2.15\"></r> (Bl., § 77, 2; 78, 5; MM, s.v.).†</s>"},"G604":{"l":"ἀποκαταλλάσσω","o":3,"ar":"<f>*† <o>ἀπο-κατ-αλλάσσω</o></f> <s><b>يصالح مصالحةً تامة</b>: <r v=\"Eph.2.16\"></r>، <r v=\"Col.1.20\"></r>، <r v=\"Col.1.21\"></r>.†</s>","en":"<f>*† <o>ἀπο-κατ-αλλάσσω</o></f> <et> <e t=\"derivation\">(cf. <x><g>καταλλάσσω</g></x>: <x><g>ἀπό</g></x> here signifies <i>completely</i>, v. Lft., <r v=\"Col.1.20\"></r>, <r v=\"Col.1.21\"></r>; Ellic., <r v=\"Eph.2.16\"></r>; but also Mey., <r v=\"Eph.2.16\"></r>),</e> </et> <s><b>to reconcile completely</b>: <r v=\"Eph.2.16\"></r>, <r v=\"Col.1.20\"></r>, <r v=\"Col.1.21\"></r>.†</s>"},"G652":{"l":"ἀπόστολος","o":80,"ar":"<f><o>ἀπόστολος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>أسطول</b>، <b>حملة بحرية</b>.</s> <s n=\"2.\"><b>رسول</b>، <b>مُرسَل في مهمة</b> (قارن <r v=\"1Kgs.14.6\"></r>): <r v=\"John.13.16\"></r>، <r v=\"2Cor.8.23\"></r>، <r v=\"Phil.2.25\"></r>.</s> <s n=\"3.\">في العهد الجديد، <b>رسول</b> للمسيح <s n=\"(a)\">بإشارة خاصة إلى الاثني عشر: <r v=\"Matt.10.2\"></r>، <r v=\"Mark.3.14\"></r>، <r v=\"Luke.11.49\"></r>، <r v=\"Eph.3.5\"></r>، <r v=\"Rev.18.20\"></r>، وفي مواضع أخرى، ويطالب القديس بولس بالمساواة معهم، <r v=\"Gal.1.1\"></r>، <r v=\"Gal.1.11\"></r> وما يليه، <r v=\"1Tim.2.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">بمعنى أوسع عن معلّمين مسيحيين بارزين، مثل برنابا، <r v=\"Acts.14.14\"></r>، وكما يبدو سلوانس وتيموثاوس أيضًا، <r v=\"1Thess.2.6\"></r>، وربما أندرونكوس ويونياس (يونيا؟)، <r v=\"Rom.16.7\"></r>؛ وعن معلمين كذبة يدّعون الرسولية: <r v=\"2Cor.11.5\"></r>، <r v=\"2Cor.11.13\"></r>، <r v=\"Rev.2.2\"></r>. </s> </s>","en":"<f><o>ἀπόστολος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποστέλλω</g></x>),</e> <e t=\"septuagint\">[in LXX; <r v=\"1Kgs.14.6\"></r> A (<h n=\"H7971\">שְׁלִיחַ</h>)*;]</e> </et> <s n=\"1.\"><b>a fleet</b>, <b>an expedition</b> (Dem.).</s> <s n=\"2.\"><b>a messenger</b>, <b>one sent on a mission</b> (Hdt., LXX, <r v=\"1Kgs.14.6\"></r>, and <g>π.</g>; v. M, <i>Pr.</i>, 37 f.; MM, s.v.; M, <i>Th.</i>, i, 2:7 and reff.): <r v=\"John.13.16\"></r>, <r v=\"2Cor.8.23\"></r>, <r v=\"Phil.2.25\"></r>.</s> <s n=\"3.\">In NT, <b>an Apostle</b> of Christ <s n=\"(a)\">with special ref. to the Twelve: <r v=\"Matt.10.2\"></r>, <r v=\"Mark.3.14\"></r>, <r v=\"Luke.11.49\"></r>, <r v=\"Eph.3.5\"></r>, <r v=\"Rev.18.20\"></r>, al., equality with whom is claimed by St. Paul, <r v=\"Gal.1.1\"></r>, <r v=\"Gal.1.11\"></r> ff, <r v=\"1Tim.2.7\"></r>, a1.;</s> <s n=\"(b)\">in a wider sense of prominent Christian teachers, as Barnabas, <r v=\"Acts.14.14\"></r>, apparently also Silvanus and Timothy, <r v=\"1Thess.2.6\"></r>, and perhaps Andronicus and Junias (Junia?), <r v=\"Rom.16.7\"></r> (v. <i>ICC</i>, in l.); of false teachers, claiming apostleship: <r v=\"2Cor.11.5\"></r>, <r v=\"2Cor.11.13\"></r>, <r v=\"Rev.2.2\"></r>. (On the different uses of the term in NT, v. Lft., <i>Gal.</i>, 92-101; Cremer, 530; <i>DB</i>, i, 126; <i>DCG</i>, i, 105; <i>Enc. Br.</i>, ii, 196 ff.)</s> </s>"},"G601":{"l":"ἀποκαλύπτω","o":26,"ar":"<f><o>ἀπο-καλύπτω</o>،</f> <s n=\"1.\">بالمعنى العام، <b>يُعلِن</b>، <b>يكشف</b>، <b>يُظهِر</b>، <s n=\"(a)\">عن الأشياء: <r v=\"Matt.10.26\"></r>، <r v=\"Luke.2.35\"></r> <r v=\"Luke.12.2\"></r>، <r v=\"1Cor.3.13\"></r>؛</s> <s n=\"(b)\">عن الأشخاص: المبني للمجهول، المسيح، <r v=\"Luke.17.30\"></r>؛ ضد المسيح، <r v=\"2Thess.2.3\"></r>، <r v=\"2Thess.2.6\"></r>، <r v=\"2Thess.2.8\"></r>.</s> </s> <s n=\"2.\">في السبعينية والعهد الجديد، بالمعنى الخاص للإعلان الإلهي: <r v=\"Matt.11.25\"></r>، <r v=\"Matt.11.27\"></r> <r v=\"Matt.16.17\"></r>، <r v=\"Luke.10.21\"></r>، <r v=\"Luke.10.22\"></r>، <r v=\"John.12.38\"></r>، <r v=\"Rom.1.17\"></r>، <r v=\"Rom.1.18\"></r> <r v=\"Rom.8.18\"></r>، <r v=\"1Cor.2.10\"></r> <r v=\"1Cor.14.30\"></r>، <r v=\"Gal.1.16\"></r> <r v=\"Gal.3.23\"></r>، <r v=\"Eph.3.5\"></r>، <r v=\"Phil.3.15\"></r>، <r v=\"1Pet.1.5\"></r>، <r v=\"1Pet.1.12\"></r> <r v=\"1Pet.5.1\"></r>.†</s>","en":"<f><o>ἀπο-καλύπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1540\">גּלה</h>;]</e> </et> <s n=\"1.\">in general sense (cl.), <b>to reveal</b>, <b>uncover</b>, <b>disclose</b>, <s n=\"(a)\">of things: <r v=\"Matt.10.26\"></r>, <r v=\"Luke.2.35\"></r> <r v=\"Luke.12.2\"></r>, <r v=\"1Cor.3.13\"></r>;</s> <s n=\"(b)\">of persons: pass., Christ, <r v=\"Luke.17.30\"></r>; Antichrist, <r v=\"2Thess.2.3\"></r>, <r v=\"2Thess.2.6\"></r>, <r v=\"2Thess.2.8\"></r>.</s> </s> <s n=\"2.\">In LXX and NT, in special sense of divine revelation: <r v=\"Matt.11.25\"></r> (on the tense, v. M, <i>Pr.</i>, 136), <r v=\"Matt.11.27\"></r> <r v=\"Matt.16.17\"></r>, <r v=\"Luke.10.21\"></r>, <r v=\"Luke.10.22\"></r>, <r v=\"John.12.38\"></r>, <r v=\"Rom.1.17\"></r>, <r v=\"Rom.1.18\"></r> <r v=\"Rom.8.18\"></r>, <r v=\"1Cor.2.10\"></r> <r v=\"1Cor.14.30\"></r>, <r v=\"Gal.1.16\"></r> <r v=\"Gal.3.23\"></r>, <r v=\"Eph.3.5\"></r>, <r v=\"Phil.3.15\"></r>, <r v=\"1Pet.1.5\"></r>, <r v=\"1Pet.1.12\"></r> <r v=\"1Pet.5.1\"></r> (Westc., <i>Eph.</i>, 178 f.; M, <i>Th.</i>, 149 f.).†</s> <sy><i>SYN.</i>: <x><g>φανερόω</g></x> (v. Thayer, 62; Cremer, 342).†</sy>"},"G629":{"l":"ἀπολύτρωσις","o":10,"ar":"<f>† <o>ἀπο-λύτρωσις</o>، <g>-εως, ἡ</g></f> <s><b>إطلاقٌ يتم بدفع فدية</b>، <b>فداء</b>، <b>نجاة</b>؛ مجازيًا، <r v=\"Heb.11.35\"></r>؛ عن النجاة بالمسيح من الشر ومن عواقب الخطية: <r v=\"Luke.21.28\"></r>، <r v=\"Rom.3.24\"></r> 8:23، <r v=\"1Cor.1.30\"></r>، <r v=\"Eph.1.7\"></r>، <r v=\"Eph.1.14\"></r> <r v=\"Eph.4.30\"></r>، <r v=\"Col.1.14\"></r>، <r v=\"Heb.9.15\"></r>. (قارن <r v=\"Rom.3.24\"></r>)†</s>","en":"<f>† <o>ἀπο-λύτρωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπολυτρόω</g></x>,<i> to release on payment of </i> <i>ransom</i>, cf. <x><g>λύτρον</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.4.30\"></r>*;]</e> </et> <s><b>release effected by payment of ransom</b>, <b>redemption</b>, <b>deliverance</b>; metaph., <r v=\"Heb.11.35\"></r>; of deliverance thr. Christ from evil and the consequences of sin: <r v=\"Luke.21.28\"></r>, <r v=\"Rom.3.24\"></r> (Vau., in l.) 8:23, <r v=\"1Cor.1.30\"></r>, <r v=\"Eph.1.7\"></r>, <r v=\"Eph.1.14\"></r> <r v=\"Eph.4.30\"></r>, <r v=\"Col.1.14\"></r>, <r v=\"Heb.9.15\"></r>. (On the extent to wh. the word retains the sense of <i>ransom</i>, v. <i>ICC</i>, <r v=\"Rom.3.24\"></r>, Westc., <i>He.</i>, 297 ff.; v. also <i>ICC</i>, <i>Eph.</i>, 11; <i>DCG</i>, ii, 605; Cremer, 410; Deiss., <i>LAE</i>, 331; Lft., <i>Notes</i>, 271, 316; Tr., <i>Syn.</i>, § lxxvii.)†</s>"},"G602":{"l":"ἀποκάλυψις","o":18,"ar":"<f><o>ἀπο-κάλυψις</o>، <g>-εως, ἡ</g></f> <s>عند الكتّاب المتأخرين: <b>كشف</b>، <b>تعرية</b>. مجازيًا، <b>إظهار</b>، <b>إعلان</b>: كشفٌ لحق إلهي، أو إظهارٌ من الله: <r v=\"Luke.2.32\"></r>، <r v=\"Rom.2.5\"></r> <r v=\"Rom.8.19\"></r> <r v=\"Rom.16.25\"></r>، <r v=\"1Cor.1.7\"></r> <r v=\"1Cor.14.6\"></r>، <r v=\"1Cor.14.26\"></r>، <r v=\"2Cor.12.1\"></r>، <r v=\"2Cor.12.7\"></r>، <r v=\"Gal.1.12\"></r> <r v=\"Gal.2.2\"></r>، <r v=\"Eph.1.17\"></r> <r v=\"Eph.3.3\"></r>، <r v=\"2Thess.1.7\"></r>، <r v=\"1Pet.1.7\"></r>، <r v=\"1Pet.1.13\"></r> <r v=\"1Pet.4.13\"></r>، <r v=\"Rev.1.1\"></r>.†</s>","en":"<f><o>ἀπο-κάλυψις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποκαλύπτω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.20.30\"></r> (<h n=\"H6172\">עֶרְוָה</h>), <r v=\"Sir.11.27\"></r> <r v=\"Sir.22.22\"></r> <r v=\"Sir.42.1\"></r>*;]</e> </et> <s><b>an uncovering</b>, <b>laying bare</b> (Plut.). Metaph., <b>a revealing</b>, <b>revelation</b>: a disclosure of divine truth, or a manifestion from God: <r v=\"Luke.2.32\"></r>, <r v=\"Rom.2.5\"></r> <r v=\"Rom.8.19\"></r> <r v=\"Rom.16.25\"></r>, <r v=\"1Cor.1.7\"></r> <r v=\"1Cor.14.6\"></r>, <r v=\"1Cor.14.26\"></r>, <r v=\"2Cor.12.1\"></r>, <r v=\"2Cor.12.7\"></r>, <r v=\"Gal.1.12\"></r> <r v=\"Gal.2.2\"></r>, <r v=\"Eph.1.17\"></r> <r v=\"Eph.3.3\"></r>, <r v=\"2Thess.1.7\"></r>, <r v=\"1Pet.1.7\"></r>, <r v=\"1Pet.1.13\"></r> <r v=\"1Pet.4.13\"></r>, <r v=\"Rev.1.1\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἐπιφάνεια</g></x>, <x><g>παρουσία</g></x>, <x><g>φανέρωσις</g></x> (v. Tr., <i>Syn.</i>, xciv; Lft., <i>Notes</i>, 102, 178; Westc, <i>Eph.</i>, 178 f.; M, <i>Th.</i>, 145 ff.; Cremer, 343).</sy>"},"G613":{"l":"ἀποκρύπτω","o":4,"ar":"<f><o>ἀπο-κρύπτω</o>،</f> <s><b>يُخفي</b>، <b>يستر</b>، <b>يكتم</b>: مع المنصوب، <r v=\"Luke.10.21\"></r>؛ المبني للمجهول، <r v=\"1Cor.2.7\"></r>، <r v=\"Eph.3.9\"></r>، <r v=\"Col.1.26\"></r>.†</s>","en":"<f><o>ἀπο-κρύπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5641\">סתר</h>;]</e> </et> <s><b>to hide</b>, <b>conceal</b>, <b>keep secret</b>: c. acc., <r v=\"Luke.10.21\"></r>; pass., <r v=\"1Cor.2.7\"></r>, <r v=\"Eph.3.9\"></r>, <r v=\"Col.1.26\"></r> (MM, s.v.).†</s>"},"G659":{"l":"ἀποτίθημι","o":11,"ar":"<f><o>ἀπο-τίθημι</o>،</f> <s><b>يخلع</b> أو <b>يطرح جانبًا</b>؛ في العهد الجديد دائمًا بالصيغة الوسطى، <s n=\"(a)\"><b>يخلع عن نفسه</b> كالثوب: <g>τ. ἱμάτια</g>، <r v=\"Acts.7.58\"></r>؛ مجازيًا، بالمعنى الأخلاقي، <b>يخلع</b>، <b>يطرح عنه</b>: <r v=\"Rom.13.12\"></r>، <r v=\"Eph.4.22\"></r>، <r v=\"Eph.4.25\"></r>، <r v=\"Col.3.8\"></r>، <r v=\"Heb.12.1\"></r>، <r v=\"Jas.1.21\"></r>، <r v=\"1Pet.2.1\"></r>؛</s> <s n=\"(b)\"><b>يحفظ بعيدًا</b>، <b>يضع</b>: <g>ἐν τ. φυλακῇ</g>، <r v=\"Matt.14.3\"></r>.†</s> </s>","en":"<f><o>ἀπο-τίθημι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5117\">נוּחַ</h> hi.;]</e> </et> <s><b>to put off</b> or <b>aside</b>; in NT always mid., <s n=\"(a)\"><b>to put off from oneself</b> as a garment: <g>τ. ἱμάτια</g>, <r v=\"Acts.7.58\"></r>; metaph., in ethical sense, <b>to put of</b>, <b>lay aside</b>: <r v=\"Rom.13.12\"></r>, <r v=\"Eph.4.22\"></r>, <r v=\"Eph.4.25\"></r>, <r v=\"Col.3.8\"></r>, <r v=\"Heb.12.1\"></r>, <r v=\"Jas.1.21\"></r>, <r v=\"1Pet.2.1\"></r>;</s> <s n=\"(b)\"><b>to stow away</b>, <b>put</b>: <g>ἐν τ. φυλακῇ</g> (MM, s.v.), <r v=\"Matt.14.3\"></r>.†</s> </s>"},"G615":{"l":"ἀποκτείνω","o":74,"ar":"<f><o>ἀπο-κτείνω</o></f> <s><b>يقتل</b>: <r v=\"Matt.14.5\"></r>، وفي مواضع أخرى؛ يليه <g>ἐν</g> للأداة (انظره)، <r v=\"Eph.2.16\"></r>، <r v=\"Rev.2.23\"></r>، وفي مواضع أخرى. مجازيًا: <r v=\"Rom.7.11\"></r>؛ <g>τ. ἔχθραν</g>، <r v=\"Eph.2.16\"></r>؛ <g>τὸ γράμμα ἀποκτείνει</g>، <r v=\"2Cor.3.6\"></r> .</s>","en":"<f><o>ἀπο-κτείνω</o></f> <et> <e t=\"derivation\">(also in late forms <g>-κτέννω</g>, <r v=\"Matt.10.28\"></r>, a1., LTTr., <g>-κτεννύω</g>, <r v=\"Mark.12.5\"></r>, WH),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2026\">הרג</h>, <h n=\"H4191\">מוּת</h>;]</e> </et> <s><b>to kill</b>: <r v=\"Matt.14.5\"></r>, al.; seq. instr. <g>ἐν</g> (q.v.), <r v=\"Eph.2.16\"></r>, <r v=\"Rev.2.23\"></r>, al. Metaph.: <r v=\"Rom.7.11\"></r>; <g>τ. ἔχθραν</g>, <r v=\"Eph.2.16\"></r>; <g>τὸ γράμμα ἀποκτείνει</g>, <r v=\"2Cor.3.6\"></r> (on the perfective force of this verb, v. M, <i>Pr.</i>, 114).</s>"},"G622":{"l":"ἀπόλλυμι","o":90,"ar":"<f><o>ἀπ-όλλυμι</o> و<o>ἀπολλύω</o>،</f> <s n=\"1.\">المبني للمعلوم، <s n=\"(1)\"><b>يُهلك تمامًا</b>، <b>يُهلك</b>، <b>يقتل</b>: <r v=\"Mark.1.24\"></r>، <r v=\"Mark.9.22\"></r>، وفي مواضع أخرى؛ <g>τ. ψνχήν</g>، <r v=\"Matt.10.28\"></r>، وفي مواضع أخرى؛</s> <s n=\"(2)\"><b>يُضيِّع تمامًا، يفقد</b>: <r v=\"Matt.10.42\"></r>، وفي مواضع أخرى؛ مجازيًا، عن الإخفاق في الخلاص، <r v=\"John.6.39\"></r> <r v=\"John.18.9\"></r>.</s> </s> <s n=\"2.\">الصيغة الوسطى، <s n=\"(1)\"><b>يهلك</b>؛ <s n=\"(a)\">عن الأشياء: <r v=\"Matt.5.29\"></r>، <r v=\"John.6.12\"></r>، <r v=\"Heb.1.11\"></r><i>(السبعينية)</i>، وفي مواضع أخرى؛</s> <s n=\"(b)\">عن الأشخاص: <r v=\"Matt.8.26\"></r>، وفي مواضع أخرى. مجازيًا، عن خسارة الحياة الأبدية، <r v=\"John.3.15\"></r>، <r v=\"John.3.16\"></r> <r v=\"John.10.28\"></r> <r v=\"John.17.12\"></r>، <r v=\"Rom.2.12\"></r>، <r v=\"1Cor.8.11\"></r> <r v=\"1Cor.15.18\"></r>، <r v=\"2Pet.3.9\"></r>. وفي <g>οἱ ἀπολλύμενοι</g>، <b>الهالكون</b>، في مقابل <g>οἱ σωζόμενοι</g> في <r v=\"1Cor.1.18\"></r> وفي مواضع أخرى، تتضح القوة «التامة» للفعل، التي تتضمن <i>اكتمال</i> عملية الهلاك؛</s> </s> <s n=\"(2)\"><b>يضيع، يكون ضالًّا</b>: <r v=\"Luke.15.4\"></r> <r v=\"Luke.21.18\"></r>. مجازيًا، على أساس العلاقة بين الراعي والقطيع، عن الفقر الروحي والابتعاد عن الله: <r v=\"Matt.10.6\"></r> <r v=\"Matt.15.24\"></r>، <r v=\"Luke.19.10\"></r>.</s> </s>","en":"<f><o>ἀπ-όλλυμι</o> and <o>ἀπολλύω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6\">אבד</h>, etc. (38 words in all)].</e> </et> <s n=\"1.\">Act., <s n=\"(1)\"><b>to destroy utterly</b>, <b>destroy</b>, <b>kill</b>: <r v=\"Mark.1.24\"></r>, <r v=\"Mark.9.22\"></r>, al.; <g>τ. ψνχήν</g>, <r v=\"Matt.10.28\"></r>, al.;</s> <s n=\"(2)\"><b>to lose utterly</b>: <r v=\"Matt.10.42\"></r>, al.; metaph., of failing to save, <r v=\"John.6.39\"></r> <r v=\"John.18.9\"></r>.</s> </s> <s n=\"2.\">Mid., <s n=\"(1)\"><b>to perish</b>; <s n=\"(a)\">of things: <r v=\"Matt.5.29\"></r>, <r v=\"John.6.12\"></r>, <r v=\"Heb.1.11\"></r><i>(LXX)</i>, al.;</s> <s n=\"(b)\">of persons: <r v=\"Matt.8.26\"></r>, al. Metaph., of loss of eternal life, <r v=\"John.3.15\"></r>, <r v=\"John.3.16\"></r> <r v=\"John.10.28\"></r> <r v=\"John.17.12\"></r>, <r v=\"Rom.2.12\"></r>, <r v=\"1Cor.8.11\"></r> <r v=\"1Cor.15.18\"></r>, <r v=\"2Pet.3.9\"></r>. In <g>οἱ ἀπολλύμενοι</g>, <b>the perishing</b>, contrasted in <r v=\"1Cor.1.18\"></r>, al., with <g>οἱ σωζόμενοι</g>, the \"perfective\" force of the verb, wh. \"implies the <i>completion</i> of the process of destruction,\" is illustrated (v. M, <i>Pr.</i>, 114 f.; M, <i>Th.</i>, ii, 2:10);</s> </s> <s n=\"(2)\"><b>to be lost</b>: <r v=\"Luke.15.4\"></r> <r v=\"Luke.21.18\"></r>. Metaph., on the basis of the relation between shepherd and flock, of spiritual destitution and alienation from God: <r v=\"Matt.10.6\"></r> <r v=\"Matt.15.24\"></r>, <r v=\"Luke.19.10\"></r> (MM, s.v.; <i>DCG</i>, i, 191 f., ii, 76, 554; Cremer, 451).</s> </s>"},"G626":{"l":"ἀπολογέομαι","o":10,"ar":"<f><o>ἀπολογέομαι</o>، <g>-οῦμαι</g></f> <s n=\"1.\"><b>يدافع عن، يحتجّ</b>: مع المنصوب، <r v=\"Rom.2.15\"></r>.</s> <s n=\"2.\"><b>يدافع عن نفسه، يحتجّ</b>: مطلقًا، <r v=\"Luke.21.14\"></r>، <r v=\"Acts.26.1\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Acts.25.8\"></r>؛ <g>τί</g>، يقدّم شيئًا دفاعًا عن نفسه، <r v=\"Luke.12.11\"></r>، <r v=\"Acts.26.24\"></r> (<g>ταῦτα</g>) <r v=\"Acts.24.10\"></r> (<g>τὰ περὶ ἐμαυτοῦ</g>)؛ <g>περί</g>، مع المضاف إليه للأشياء، و<g>ἐπί</g>، مع المضاف إليه للأشخاص، <r v=\"Acts.26.2\"></r>؛ مع القابل للأشخاص، <r v=\"Acts.19.33\"></r>، <r v=\"2Cor.12.19\"></r>.†</s>","en":"<f><o>ἀπολογέομαι</o>, <g>-οῦμαι</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπό</g></x>, <x><g>λόγος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.12.1\"></r> (<h n=\"H???\">ויב</h><i>perhaps a misspelling of ריב #7378</i>) <r v=\"Jer.31.6\"></r>, <r v=\"2Macc.13.26\"></r>*;]</e> </et> <s n=\"1.\"><b>to defend</b>: c. acc., <r v=\"Rom.2.15\"></r>.</s> <s n=\"2.\"><b>to defend one's self</b>: absol., <r v=\"Luke.21.14\"></r>, <r v=\"Acts.26.1\"></r>; seq. <g>ὅτι</g>, <r v=\"Acts.25.8\"></r>; <g>τί</g>, to adduce something in one's defence, <r v=\"Luke.12.11\"></r>, <r v=\"Acts.26.24\"></r> (<g>ταῦτα</g>) <r v=\"Acts.24.10\"></r> (<g>τὰ περὶ ἐμαυτοῦ</g>); <g>περί</g>, c. gen. rei, and <g>ἐπί</g>, c. gen. pers., <r v=\"Acts.26.2\"></r>; c. dat. pers., <r v=\"Acts.19.33\"></r>, <r v=\"2Cor.12.19\"></r>.†</s>"},"G603":{"l":"ἀποκαραδοκία","o":2,"ar":"<f>*† <o>ἀπο-καραδοκία</o>، <g>-ας, ἡ</g></f> <s><b>الترقُّب بمدّ الرأس</b>، <b>الانتظار بشوق ولهفة</b>، <r v=\"Rom.8.19\"></r>، <r v=\"Phil.1.20\"></r>.†</s>","en":"<f>*† <o>ἀπο-καραδοκία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποκαραδοκέω</g></x>, used by Aq. in <r v=\"Ps.37.7\"></r> for <h n=\"H????\">התהוֹלל</h>; &lt; <x><g>ἀπό</g></x>, <x><g>κάρα</g></x> <i>the head</i>, <x><g>δοκέω</g></x>, in Ion., <i>to watch</i>),</e> </et> <s><b>to watch with outstretched head</b>, <b>watch anxiously</b> (Polyb., <g>π.</g>; v. Deiss., <i>LAE</i>, 374<i>5</i>, 377 f.), <r v=\"Rom.8.19\"></r>, <r v=\"Phil.1.20\"></r> (Lft., in l.; Cremer, 177).†</s>"},"G676":{"l":"ἀπρόσιτος","o":1,"ar":"<f>*† <o>ἀ-πρόσ-ιτος</o>، <g>-ον</g></f> <s><b>لا يُدنى منه</b>: <g>φῶς</g>، <r v=\"1Tim.6.16\"></r>.†</s>","en":"<f>*† <o>ἀ-πρόσ-ιτος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>πρόσειμι</g></x>, <i>to go to</i>),</e> </et> <s><b>unapproachable</b>: <g>φῶς</g>, <r v=\"1Tim.6.16\"></r>.†</s>"},"G646":{"l":"ἀποστασία","o":2,"ar":"<f>† <o>ἀποστασία</o>، <g>-ας, ἡ</g></f> <s><b>ارتداد</b>، <b>انشقاق</b>، <b>تمرّد</b>؛ في اليونانية المتأخرة بدلاً من <g>ἀπόστασις</g> الكلاسيكية، وكثيرًا بمعنى التمرد السياسي؛ وفي السبعينية (مثلاً <r v=\"Josh.22.22\"></r>، <r v=\"2Chr.29.19\"></r>، <r v=\"Jer.2.19\"></r>) والعهد الجديد دائمًا عن الارتداد الديني: <r v=\"Acts.21.21\"></r>، <r v=\"2Thess.2.3\"></r>.†</s>","en":"<f>† <o>ἀποστασία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀφίστημι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4604\">מַעַל</h>, etc.;]</e> </et> <s><b>defection</b>, <b>apostasy</b>, <b>revolt</b>; in late Gk. (MM, <i>Exp.</i>, viii; Lft., <i>Notes</i>, 111; Cremer, 308) for cl. <g>ἀπόστασις</g>, freq. in sense of political revolt, in LXX (e.g. <r v=\"Josh.22.22\"></r>, <r v=\"2Chr.29.19\"></r>, <r v=\"Jer.2.19\"></r>) and NT always of religious apostasy: <r v=\"Acts.21.21\"></r>, <r v=\"2Thess.2.3\"></r>.†</s>"},"G610":{"l":"ἀπόκριμα","o":1,"ar":"<f>*† <o>ἀπό-κριμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">بالمعنى الأصلي: <b>حكم قضائي</b>: <r v=\"2Cor.1.9\"></r>.</s> <s n=\"2.\"><b>جواب</b>: <r v=\"2Cor.1.9\"></r>.†</s>","en":"<f>*† <o>ἀπό-κριμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποκρίνω</g></x>);</e> </et> <s n=\"1.\">prop., <b>a judicial sentence</b>: <r v=\"2Cor.1.9\"></r>, R, mg.</s> <s n=\"2.\"><b>an answer</b> (v. Thayer, s.v.): <r v=\"2Cor.1.9\"></r>, R, txt. (In FlJ, <i>Ant.</i>, xiv, 10, 6, of a rescript of the Senate; in Inscr. of an official decision, Deiss., <i>BS</i>, 257; a reply to a deputation, MM, s.v.: cf. also Cremer, 375).†</s>"},"G606":{"l":"ἀπόκειμαι","o":4,"ar":"<f><o>ἀπό-κειμαι</o>،</f> <s><b>يكون موضوعًا</b>، <b>مُدَّخرًا</b>، <b>محفوظًا جانبًا</b>: <r v=\"Luke.19.20\"></r>. مجازيًا، مع قابل الشخص: <b>يكون محفوظًا، مُعيَّنًا</b>: <r v=\"Col.1.5\"></r>، <r v=\"2Tim.4.8\"></r>، <r v=\"Heb.9.27\"></r>.†</s>","en":"<f><o>ἀπό-κειμαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.49.10\"></r> (<h n=\"H7886\">שִׁילֹה</h>), <r v=\"Job.38.23\"></r> (<h n=\"H2820\">חשׂךְ</h>), <r v=\"2Macc.12.45\"></r>, <r v=\"4Macc.8.11\"></r>*;]</e> </et> <s><b>to be laid up</b>, <b>in store</b>, <b>laid away</b>: <r v=\"Luke.19.20\"></r>. Metaph., c. dat. pers., <b>to be reserved</b> (Dem., Plat.; and v. MM, s.v.): <r v=\"Col.1.5\"></r>, <r v=\"2Tim.4.8\"></r>, <r v=\"Heb.9.27\"></r>.†</s>"},"G664":{"l":"ἀποτόμως","o":2,"ar":"<f>** <o>ἀποτόμως</o>،</f> ظرف، <s><b>بحدّة</b>، <b>باقتضاب</b>، ومن ثمَّ <b>بصرامة</b>، <b>بشدة</b>: <r v=\"2Cor.13.10\"></r>، <r v=\"Titus.1.13\"></r>.†</s>","en":"<f>** <o>ἀποτόμως</o>,</f> adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.5.22\"></r>*;]</e> </et> <s><b>abruptly</b>, <b>curtly</b>, hence <b>sharply</b>, <b>severely</b>: <r v=\"2Cor.13.10\"></r>, <r v=\"Titus.1.13\"></r> (MM, s.v.).†</s>"},"G693":{"l":"ἀργύρεος","o":3,"ar":"<f><o>ἀργύρεος</o>، <g>-οῦς, -ᾶ, -οῦν</g></f> <s><b>فضّي، من فضة</b>: <r v=\"Acts.19.24\"></r>، <r v=\"2Tim.2.20\"></r>، <r v=\"Rev.9.20\"></r>.†</s>","en":"<f><o>ἀργύρεος</o> (v. MM, s.v.), <g>-οῦς, -ᾶ, -οῦν</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄργυρος</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3701\">כֶּסֶף</h>;]</e> </et> <s><b>of silver</b>: <r v=\"Acts.19.24\"></r> (WH, br.), <r v=\"2Tim.2.20\"></r>, <r v=\"Rev.9.20\"></r>.†</s>"},"G655":{"l":"ἀποστυγέω","o":1,"ar":"<f>* <o>ἀπο-στυγέω</o>، <g>-ῶ</g></f> <s><b>يكره، يمقت</b>: <r v=\"Rom.12.9\"></r>.†</s>","en":"<f>* <o>ἀπο-στυγέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στυγέω</g></x>, to hate),</e> </et> <s><b>to abhor</b>: <r v=\"Rom.12.9\"></r>.†</s>"},"G611":{"l":"ἀποκρίνω","o":232,"ar":"<f><o>ἀπο-κρίνω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>فصل</b>، <b>ميّز</b>.</s> <s n=\"2.\">في اليونانية الكلاسيكية: <b>اختار</b>. والصيغة الوسطى: <b>أجاب</b>: <r v=\"Matt.27.12\"></r>، <r v=\"Mark.14.61\"></r>، <r v=\"Luke.3.16\"></r>، <r v=\"Luke.23.9\"></r>، <r v=\"John.5.17\"></r>، <r v=\"John.5.19\"></r>، <r v=\"Acts.3.12\"></r>. وفي اليونانية المتأخرة يُستعمل المبني للمجهول أيضًا بهذا المعنى، وصيغ المبني للمجهول هي الأكثر في العهد الجديد؛ <s n=\"(a)\">بالمعنى العام: مطلقًا، <r v=\"Mark.12.34\"></r>؛ مع منصوب الشيء، <r v=\"Matt.22.46\"></r>؛ مع قابل الشخص، <r v=\"Matt.12.38\"></r>؛ يليه <g>πρός</g>، <r v=\"Acts.25.16\"></r>؛</s> <s n=\"(b)\">على الطريقة العبرية: <s n=\"(i)\">مثل <h n=\"H6030\">ענה</h>: <b>ابتدأ الكلام</b>، <b>أخذ في الحديث</b>: <r v=\"Matt.11.25\"></r>، وفي مواضع أخرى،</s> <s n=\"(ii)\">زائدًا، كما في العبارة العبرية <h n=\"H3282,H559\">וַיַּעַן וַיּאֹמֶר</h>: <g>ἀποκριθεὶς εἶπε</g>، <r v=\"Matt.4.4\"></r>؛ <g>ἔφη</g>، <r v=\"Matt.8.8\"></r>؛ <g>λέγει</g>، <r v=\"Mark.3.33\"></r>؛ وهو الأكثر في إنجيل يوحنا (<g>ἀπεκ. κ. εἶπε</g>)، <r v=\"John.1.49\"></r>.</s> </s> </s>","en":"<f><o>ἀπο-κρίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6030\">ענה</h>;]</e> </et> <e t=\"derivation\">in cl.,</e> <s n=\"1.\"><b>to separate</b>, <b>distinguish</b>.</s> <s n=\"2.\"><b>to choose</b>. Mid., <b>to answer</b>: <r v=\"Matt.27.12\"></r>, <r v=\"Mark.14.61\"></r>, <r v=\"Luke.3.16\"></r> <r v=\"Luke.23.9\"></r>, <r v=\"John.5.17\"></r>, <r v=\"John.5.19\"></r>, <r v=\"Acts.3.12\"></r>. In late Gk. the pass, also is used in this sense, and pass. forms are the more freq. in NT (M, <i>Pr.</i>, 39, 161; MM, s.v.); <s n=\"(a)\">in general sense: absol., <r v=\"Mark.12.34\"></r>; c. acc. rei, <r v=\"Matt.22.46\"></r>; c. dat. pers., <r v=\"Matt.12.38\"></r>; seq. <g>πρός</g>, <r v=\"Acts.25.16\"></r>;</s> <s n=\"(b)\">Hebraistically <s n=\"(i)\">like <h n=\"H6030\">ענה</h>, <b>to begin to speak</b>, <b>take up the conversation</b> (Kennedy, <i>Sources</i>, 124 f.): <r v=\"Matt.11.25\"></r>, al.,</s> <s n=\"(ii)\">redundant, as in the Heb. phrase <h n=\"H3282,H559\">וַיַּעַן וַיּאֹמֶר</h> (Dalman, <i>Words</i>, 24 f., 38; M, <i>Pr.</i>, 14; Bl., § 58, 4; 74, 2; Cremer, 374): <g>ἀποκριθεὶς εἶπε</g>, <r v=\"Matt.4.4\"></r>; <g>ἔφη</g>, <r v=\"Matt.8.8\"></r>; <g>λέγει</g>, <r v=\"Mark.3.33\"></r>; in Jo most freq. (<g>ἀπεκ. κ. εἶπε</g>, <r v=\"John.1.49\"></r>.</s> </s> </s>"},"G609":{"l":"ἀποκόπτω","o":6,"ar":"<f><o>ἀπο-κόπτω</o>،</f> <s><b>قطع</b>: <r v=\"Mark.9.43\"></r>، <r v=\"Mark.9.45\"></r>، <r v=\"John.18.10\"></r>، <r v=\"John.18.26\"></r>، <r v=\"Acts.27.32\"></r>. والصيغة الوسطى: <b>قطع نفسه (خصى نفسه)</b>، <b>جعل نفسه يُقطَع</b>: <r v=\"Gal.5.12\"></r> (قارن <r v=\"Deut.23.1\"></r> في السبعينية).†</s>","en":"<f><o>ἀπο-κόπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7112\">קצץ</h>, <h n=\"H3772\">כּרת</h>, etc.;]</e> </et> <s><b>to cut off</b>: <r v=\"Mark.9.43\"></r>, <r v=\"Mark.9.45\"></r>, <r v=\"John.18.10\"></r>, <r v=\"John.18.26\"></r>, <r v=\"Acts.27.32\"></r>. Mid., <b>to mutilate oneself</b>, <b>have oneself mutilated</b>: <r v=\"Gal.5.12\"></r> (cf. <r v=\"Deut.23.1\"></r> LXX; and v. Cremer, 751; MM, s.v.).†</s>"},"G667":{"l":"ἀποφέρω","o":9,"ar":"<f><o>ἀπο-φέρω</o>،</f> <s><b>حمل بعيدًا</b>، <b>نقل</b>، أو <b>اقتاد بعيدًا</b>: مع المنصوب، <r v=\"Mark.15.1\"></r>، <r v=\"1Cor.16.3\"></r>، <r v=\"Rev.17.3\"></r> <r v=\"Rev.21.10\"></r>. المبني للمجهول، <r v=\"Luke.16.22\"></r>، <r v=\"Acts.19.12\"></r>.†</s>","en":"<f><o>ἀπο-φέρω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1980\">הלךְ</h>, etc.;]</e> </et> <s><b>to carry off</b>, <b>bear</b>, or <b>lead away</b>: c. acc., <r v=\"Mark.15.1\"></r>, <r v=\"1Cor.16.3\"></r>, <r v=\"Rev.17.3\"></r> <r v=\"Rev.21.10\"></r>. Pass., <r v=\"Luke.16.22\"></r>, <r v=\"Acts.19.12\"></r>.†</s>"},"G642":{"l":"ἀπορφανίζω","o":1,"ar":"<f>* <o>ἀπ-ορφανίζω</o></f> <s><b>فُجع، صار يتيمًا، حُرم</b> (أصلاً <i>من أحد الوالدين</i>)؛ مجازيًا، <r v=\"1Thess.2.17\"></r>.†</s>","en":"<f>* <o>ἀπ-ορφανίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπό</g></x>, <x><g>ὀρφανός</g></x>),</e> </et> <s><b>to be bereaved</b> (prop., <i>of a parent</i>, Lft., <i>Notes</i>, 36); metaph., <r v=\"1Thess.2.17\"></r> (where Field thinks it = <x><g>χωρισθέντες</g></x>, <i>Notes</i>, 199).†</s>"},"G649":{"l":"ἀποστέλλω","o":136,"ar":"<f><o>ἀπο-στέλλω</o>،</f> <s>أصلاً: <b>أرسل بعيدًا</b>، <b>بعث</b> في مهمة؛ <s n=\"1.\"><b>أرسل</b> بتكليف أو في خدمة؛ <s n=\"(a)\">عن الأشخاص: المسيح، <r v=\"Matt.10.40\"></r>؛ الرسل، <r v=\"Matt.10.16\"></r>؛ العبيد، <r v=\"Mark.12.2\"></r>؛ الملائكة، <r v=\"Mark.13.27\"></r>؛</s> <s n=\"(b)\">عن الأشياء: <g>ὄνος</g>، <r v=\"Matt.21.3\"></r>؛ <g>τὸ δρέπανον</g>، <r v=\"Mark.4.29\"></r>؛ <g>τ. λόγον</g>، <r v=\"Acts.10.36\"></r>؛ <g>τ. ἐπαγγελίαν</g> (أي الروح القدس الموعود به)، <r v=\"Luke.24.49\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.20.2\"></r>، <r v=\"Luke.11.49\"></r>، <r v=\"John.3.17\"></r>؛ <g>ὀπίσω</g>، <r v=\"Luke.19.14\"></r>؛ <g>ἔμπροσθεν</g>، <r v=\"John.3.28\"></r>؛ <g>πρὸ προσώπου</g>، <r v=\"Matt.11.10\"></r>؛ <g>πρός</g>، <r v=\"Matt.21.34\"></r>؛ مع الإشارة إلى المُرسِل أو مكان الانطلاق: <g>ἀπό</g>، <r v=\"Luke.1.26\"></r>؛ <g>παρά</g>، <r v=\"John.1.6\"></r>؛ <g>ἐκ</g>، <r v=\"John.1.19\"></r>؛ <g>ὑπό</g>، <r v=\"Acts.10.17\"></r>؛ يليه المصدر، <r v=\"Mark.3.14\"></r>، وفي مواضع أخرى؛ <g>ἵνα</g>، <r v=\"Mark.12.2\"></r>، وفي مواضع أخرى؛ <g>εἰς</g> (للغرض)، <r v=\"Heb.1.14\"></r>؛ بدون مفعول مباشر: يليه <g>πρός</g>، <r v=\"John.5.33\"></r>؛ <g>λέγων</g>، <r v=\"John.11.3\"></r>؛ <g>ἀποστείλας</g>، مع الإخباري، <r v=\"Matt.2.16\"></r>، <r v=\"Acts.7.14\"></r>، <r v=\"Rev.1.1\"></r>.</s> </s> <s n=\"2.\"><b>صرف</b>، <b>أطلق</b>: <r v=\"Luke.4.18\"></r>، <r v=\"Mark.5.10\"></r> <r v=\"Mark.8.26\"></r> <r v=\"Mark.12.3\"></r> (قارن <x><g>ἐξ-</g></x>، <x><g>συν-αποστέλλω</g></x>).</s> </s>","en":"<f><o>ἀπο-στέλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX very freq., almost always for <h n=\"H7971\">שׁלח</h>;]</e> </et> <s>prop., <b>to send away</b>, <b>to dispatch</b> on service; <s n=\"1.\"><b>to send</b> with a commission, or on service; <s n=\"(a)\">of persons: Christ, <r v=\"Matt.10.40\"></r>; the apostles, <r v=\"Matt.10.16\"></r>; servants, <r v=\"Mark.12.2\"></r>; angels, <r v=\"Mark.13.27\"></r>;</s> <s n=\"(b)\">of things: <g>ὄνος</g>, <r v=\"Matt.21.3\"></r>; <g>τὸ δρέπανον</g>, <r v=\"Mark.4.29\"></r>; <g>τ. λόγον</g>, <r v=\"Acts.10.36\"></r>; <g>τ. ἐπαγγελίαν</g> (i.e. the promised Holy Spirit), <r v=\"Luke.24.49\"></r>, Rec.; seq. <g>εἰς</g>, <r v=\"Matt.20.2\"></r>, <r v=\"Luke.11.49\"></r>, <r v=\"John.3.17\"></r>; <g>ὀπίσω</g>, <r v=\"Luke.19.14\"></r>; <g>ἔμπροσθεν</g>, <r v=\"John.3.28\"></r>; <g>πρὸ προσώπου</g>, <r v=\"Matt.11.10\"></r>; <g>πρός</g>, <r v=\"Matt.21.34\"></r>; with ref. to sender or place of departure: <g>ἀπό</g>, <r v=\"Luke.1.26\"></r> (Rec. <g>ὑπό</g>); <g>παρά</g>, <r v=\"John.1.6\"></r>; <g>ἐκ</g>, <r v=\"John.1.19\"></r>; <g>ὑπό</g>, <r v=\"Acts.10.17\"></r> (Rec. <g>ἀπό</g>); seq. inf., <r v=\"Mark.3.14\"></r>, al.; <g>ἵνα</g>, <r v=\"Mark.12.2\"></r>, al.; <g>εἰς</g> (of purpose), <r v=\"Heb.1.14\"></r>; without direct obj.: seq. <g>πρός</g>, <r v=\"John.5.33\"></r>; <g>λέγων</g>, <r v=\"John.11.3\"></r>; <g>ἀποστείλας</g>, c. indic., <r v=\"Matt.2.16\"></r>, <r v=\"Acts.7.14\"></r>, <r v=\"Rev.1.1\"></r>.</s> </s> <s n=\"2.\"><b>to send away</b>, <b>dismiss</b>: <r v=\"Luke.4.18\"></r>, <r v=\"Mark.5.10\"></r> <r v=\"Mark.8.26\"></r> <r v=\"Mark.12.3\"></r> (cf. <x><g>ἐξ-</g></x>, <x><g>συν-αποστέλλω</g></x>).</s> </s> <sy><i>SYN.</i>: <x><g>πέμπω</g></x>, the general term. <g>ἀ.</g> \"suggests official or authoritative sending\" (v. Thayer, s.v. <g>πέμπω</g>; Westc., <i>Jo.</i>, 298; <i>Epp. Jo.</i>, 125; Cremer, 529; MM, s.v.).</sy>"},"G685":{"l":"ἀρά","o":1,"ar":"<f><o>ἀρά</o>، <g>-ᾶς, ἡ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>صلاة، دعاء</b>.</s> <s n=\"2.\"><b>لعنة</b>، <b>دعاء بالشر</b>: <r v=\"Rom.3.14\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>ἀρά</o>, <g>-ᾶς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H422\">אלה</h>];</e> </et> <s n=\"1.\"><b>a prayer</b> (MM, s.v.).</s> <s n=\"2.\">(as in Homer) <b>a curse</b>, <b>malediction</b>: <r v=\"Rom.3.14\"></r><i>(LXX)</i>.†</s>"},"G663":{"l":"ἀποτομία","o":2,"ar":"<f>**† <o>ἀποτομία</o>، <g>-ας, ἡ</g></f> <s><b>انحدار شديد</b>، <b>حِدّة</b>؛ مجازيًا، <b>صرامة</b>: <r v=\"Rom.11.22\"></r>.†</s>","en":"<f>**† <o>ἀποτομία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἀποτέμνω</g>, <i>to cut of</i>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Jer.28.35\"></r>, <r v=\"Nah.3.1\"></r>*;]</e> </et> <s><b>steepness</b>, <b>sharpness</b>; metaph., <b>severity</b> (MM, s.v.): <r v=\"Rom.11.22\"></r>.†</s>"},"G662":{"l":"ἀποτολμάω","o":1,"ar":"<f>* <o>ἀπο-τολμάω</o>، <g>-ῶ</g>،</f> <s><b>تجاسر جدًّا</b>، <b>أقدم بجرأة</b>: <r v=\"Rom.10.20\"></r>.†</s>","en":"<f>* <o>ἀπο-τολμάω</o>, <g>-ῶ</g>,</f> <s><b>to be quite bold</b>, <b>make a bold venture</b>: <r v=\"Rom.10.20\"></r>.†</s>"},"G654":{"l":"ἀποστρέφω","o":44,"ar":"<f><o>ἀπο-στρέφω</o>،</f> <s>متعدٍّ، مع المنصوب، <s n=\"(a)\"><b>يردّ، يُبعد</b>، <b>يُزيل</b>: <r v=\"Rom.11.26\"></r>، <r v=\"2Tim.4.4\"></r>؛ مجازيًا، يصرف عن الولاء: <b>يُفسد، يضلّل</b>: <r v=\"Luke.23.14\"></r>؛</s> <s n=\"(b)\"><b>يردّ، يُرجع</b>: <g>μάχαιραν</g> (السيف)، <r v=\"Matt.26.52\"></r>. المبني للمجهول، بمعنى انعكاسي: <b>يرتدّ عن، يُعرض عن</b>: مع المنصوب، <r v=\"Matt.5.42\"></r>، <r v=\"2Tim.1.15\"></r>، <r v=\"Titus.1.14\"></r>، <r v=\"Heb.12.25\"></r>؛ وكذلك المبني للمعلوم مطلقًا، <r v=\"Acts.3.26\"></r> (قارن <r v=\"Sir.8.5\"></r>).†</s> </s>","en":"<f><o>ἀπο-στρέφω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7725\">שׁוּב</h>;]</e> </et> <s>trans., c. acc., <s n=\"(a)\"><b>to turn away</b>, <b>remove</b>: <r v=\"Rom.11.26\"></r>, <r v=\"2Tim.4.4\"></r>; metaph., to turn away from allegiance, <b>pervert</b>: <r v=\"Luke.23.14\"></r>;</s> <s n=\"(b)\"><b>to turn back</b>, <b>return</b>: <g>μάχαιραν</g>, <r v=\"Matt.26.52\"></r>. Pass., reflex., <b>to turn oneself away from</b>: c. acc., <r v=\"Matt.5.42\"></r>, <r v=\"2Tim.1.15\"></r>, <r v=\"Titus.1.14\"></r>, <r v=\"Heb.12.25\"></r>; so act., absol., <r v=\"Acts.3.26\"></r> (cf. <r v=\"Sir.8.5\"></r>; Bl., § 53, 1; Cremer, 880).†</s> </s>"},"G614":{"l":"ἀπόκρυφος","o":3,"ar":"<f><o>ἀπόκρυφος</o>، <g>-ον</g></f> <s><b>خفيّ، مكتوم</b>: <r v=\"Mark.4.22\"></r>، <r v=\"Luke.8.17\"></r>، <r v=\"Col.2.3\"></r>.†</s>","en":"<f><o>ἀπόκρυφος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποκρύπτω</g></x>),</e> <e t=\"septuagint\">[in LXX Chiefly for <h n=\"H5643\">סֵתֶר</h>;]</e> </et> <s><b>hidden</b>: <r v=\"Mark.4.22\"></r>, <r v=\"Luke.8.17\"></r>, <r v=\"Col.2.3\"></r> (v. Lft., in l.; MM, s.v.).†</s>"},"G677":{"l":"ἀπρόσκοπος","o":3,"ar":"<f>**† <o>ἀπρόσκοπος</o>، <g>-ον</g></f> <s n=\"1.\">بمعنى المبني للمعلوم: <b>غير معثِر</b>: مجازيًا، عن عدم إيقاع الآخرين في الخطية، <r v=\"1Cor.10.32\"></r>.</s> <s n=\"2.\">بمعنى المبني للمجهول: <b>غير عاثر</b>، <b>بلا عثرة</b>، <b>بلا لوم</b>: <r v=\"Acts.24.16\"></r>، <r v=\"Phil.1.10\"></r>.†</s>","en":"<f>**† <o>ἀπρόσκοπος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>προσκόπτω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.32.21\"></r>, <r v=\"3Macc.3.8\"></r>*;]</e> </et> <s n=\"1.\">act., <b>not causing to stumble</b>: metaph., of not leading others into sin, <r v=\"1Cor.10.32\"></r>.</s> <s n=\"2.\">Pass., <b>not stumbling</b>, <b>without offence</b>, <b>blameless</b>: <r v=\"Acts.24.16\"></r>, <r v=\"Phil.1.10\"></r> (for exx., v. MM, s.v.).†</s>"},"G628":{"l":"ἀπολούω","o":2,"ar":"<f><o>ἀπο-λούω</o>،</f> <s><b>يغسل</b>، <b>يزيل بالغسل</b>؛ في الصيغة الوسطى، مجازيًا، مع المنصوب للشيء: <b>يغسل عن نفسه</b>: <g>ἁμαρτίας</g>، <r v=\"Acts.22.16\"></r>؛ مطلقًا، <g>ἀπελούσασθε</g>: <b>اغتسلتم</b>، <r v=\"1Cor.6.11\"></r>.†</s>","en":"<f><o>ἀπο-λούω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.9.30\"></r> (<h n=\"H7364\">רחץ</h>)*;]</e> </et> <s><b>to wash off</b>, <b>wash away</b>; mid., metaph., c. acc. rei, <b>to wash off oneself</b>: <g>ἁμαρτίας</g>, <r v=\"Acts.22.16\"></r>; absol., <g>ἀπελούσασθε</g>, <b>ye washed yourselves clean</b> (cf. Cremer, 406), <r v=\"1Cor.6.11\"></r>.†</s>"},"G666":{"l":"ἀπουσία","o":1,"ar":"<f>* <o>ἀπουσία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>غياب</b>: <r v=\"Phil.2.12\"></r>.</s> <s n=\"2.\">عند الكتّاب المتأخرين: <b>نقص</b>، <b>هدر</b>.†</s>","en":"<f>* <o>ἀπουσία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄπειμι</g></x>);</e> </et> <s n=\"1.\"><b>absence</b> (Æsch., Thuc.): <r v=\"Phil.2.12\"></r>.</s> <s n=\"2.\"><b>deficiency</b>, <b>waste</b> (MM, s.v).†</s>"},"G619":{"l":"ἀπόλαυσις","o":2,"ar":"<f>** <o>ἀπόλαυσις</o>، <g>-εως, ἡ</g></f> <s><b>تمتّع</b>: <r v=\"1Tim.6.17\"></r>، <r v=\"Heb.11.25\"></r>.†</s>","en":"<f>** <o>ἀπόλαυσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπολαύω</g></x>, <i>to take of</i>, <i>enjoy</i> a thing),</e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.7.16\"></r>*;]</e> </et> <s><b>enjoyment</b>: <r v=\"1Tim.6.17\"></r>, <r v=\"Heb.11.25\"></r> (for late exx., v. MM, s.v.).†</s>"},"G627":{"l":"ἀπολογία","o":8,"ar":"<f>** <o>ἀπολογία</o>، <g>-ας, ἡ</g></f> <s><b>احتجاج، دفاع (عن النفس)</b>: <r v=\"Acts.25.16\"></r>، <r v=\"2Cor.7.11\"></r>، <r v=\"Phil.1.7\"></r>، <r v=\"Phil.1.16\"></r>، <r v=\"2Tim.4.16\"></r>؛ مع القابل للشخص، <r v=\"1Cor.9.3\"></r>، <r v=\"1Pet.3.15\"></r>؛ يليه <g>πρός</g>، <r v=\"Acts.22.1\"></r>.†</s>","en":"<f>** <o>ἀπολογία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπολογέομαι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.6.10\"></r>*;]</e> </et> <s><b>a speech in defence</b>: <r v=\"Acts.25.16\"></r>, <r v=\"2Cor.7.11\"></r>, <r v=\"Phil.1.7\"></r>, <r v=\"Phil.1.16\"></r>, <r v=\"2Tim.4.16\"></r>; c. dat. pers., <r v=\"1Cor.9.3\"></r>, <r v=\"1Pet.3.15\"></r>; seq. <g>πρός</g>, <r v=\"Acts.22.1\"></r>.†</s>"},"G688":{"l":"Ἀραβία","o":2,"ar":"<f><o>Ἀραβία</o>، <g>-ας, ἡ</g>.</f> <s><b>العربية (بلاد العرب)</b>: <r v=\"Gal.1.17\"></r> <r v=\"Gal.4.25\"></r>.†</s>","en":"<f><o>Ἀραβία</o>, <g>-ας, ἡ</g>.</f> <s><b>Arabia</b>: <r v=\"Gal.1.17\"></r> <r v=\"Gal.4.25\"></r>.†</s>"},"G618":{"l":"ἀπολαμβάνω","o":15,"ar":"<f><o>ἀπο-λαμβάνω</o>،</f> <s n=\"1.\"><b>أخذ من</b> آخر؛ مطلقًا: <b>نال ما يستحقه</b>، <b>استوفى</b>: <r v=\"Luke.16.25\"></r>، <r v=\"Luke.18.30\"></r> (وفي قراءة أخرى <g>λάβῃ</g>)، <r v=\"Luke.23.41\"></r>، <r v=\"Rom.1.27\"></r>، <r v=\"Gal.4.5\"></r>، <r v=\"Col.3.24\"></r>، <r v=\"2John.1.8\"></r>.</s> <s n=\"2.\"><b>استردّ</b>، <b>أخذ ثانيةً</b>: <r v=\"Luke.6.34\"></r>، <r v=\"Luke.15.27\"></r>.</s> <s n=\"3.\"><b>أخذ على انفراد</b> أو <b>جانبًا</b>: <r v=\"Mark.7.33\"></r>.†</s>","en":"<f><o>ἀπο-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Num.34.14\"></r> (<h n=\"H3947\">לקח</h> (<r v=\"Deut.25.5\"></r> A, <r v=\"Isa.5.17\"></r>, <r v=\"2Macc.4.46\"></r> <r v=\"2Macc.6.21\"></r> <r v=\"2Macc.8.6\"></r>, <r v=\"4Macc.18.23\"></r>*;]</e> </et> <s n=\"1.\"><b>to receive from</b> another; absol., <b>to receive as one's due</b>: <r v=\"Luke.16.25\"></r> <r v=\"Luke.18.30\"></r> (v.l. <g>λάβῃ</g>) <r v=\"Luke.23.41\"></r>, <r v=\"Rom.1.27\"></r>, <r v=\"Gal.4.5\"></r>, <r v=\"Col.3.24\"></r>, <r v=\"2John.1.8\"></r>.</s> <s n=\"2.\"><b>to receive back</b>: <r v=\"Luke.6.34\"></r> <r v=\"Luke.15.27\"></r>.</s> <s n=\"3.\"><b>to take apart</b> or <b>aside</b>: <r v=\"Mark.7.33\"></r> (cf. use in <g>π.</g> of the recluses of the Serapeum; MM, s.v.).†</s>"},"G696":{"l":"ἄργυρος","o":5,"ar":"<f><o>ἄργυρος</o>، <g>-ου, ὁ</g></f> <s><b>فضة</b>: <r v=\"Matt.10.9\"></r>، <r v=\"Acts.17.29\"></r>، <r v=\"Jas.5.5\"></r>، <r v=\"Rev.18.12\"></r>.†</s>","en":"<f><o>ἄργυρος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀργός</g></x>, <i>shining</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3701\">כֶּסֶף</h>;]</e> </et> <s><b>silver</b> (on its relation to <x><g>ἀργύριον</g></x>, v. MM, s.v.): <r v=\"Matt.10.9\"></r>, <r v=\"Acts.17.29\"></r>, <r v=\"Jas.5.5\"></r>, <r v=\"Rev.18.12\"></r>.†</s>"},"G650":{"l":"ἀποστερέω","o":6,"ar":"<f><o>ἀπο-στερέω</o>، <g>-ῶ</g></f> <s><b>يسلب</b>، <b>يحرم من</b>، <b>ينهب</b>: مطلقًا، <r v=\"Mark.10.19\"></r>، <r v=\"1Cor.6.8\"></r>؛ مع المنصوب للشخص، <r v=\"1Cor.7.5\"></r>. الصيغة الوسطى، <b>يحتمل الحرمان</b>: <r v=\"1Cor.6.7\"></r>؛ المبني للمجهول، <g>ἀπεστερημένοι</g>، <b>محرومون من</b>: <r v=\"1Tim.6.5\"></r>.†</s>","en":"<f><o>ἀπο-στερέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>στερέω</g></x>, <i>to rob</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.21.10\"></r> (<h n=\"H1639\">גּרע</h>), <r v=\"Deut.24.14\"></r> (<h n=\"H6231\">עשׁק</h>), <r v=\"Mal.3.5\"></r>, <r v=\"Sir.4.1\"></r> <r v=\"Sir.29.6\"></r>, <r v=\"Sir.29.7\"></r> <r v=\"Sir.34.21\"></r>, <r v=\"Sir.34.22\"></r>*;]</e> </et> <s><b>to defraud</b>, <b>deprive of</b>, <b>despoil</b> (in cl. chiefly of the misappropriation of trust funds, Field, <i>Notes</i>, 33; cf. MM, s.v.): absol., <r v=\"Mark.10.19\"></r>, <r v=\"1Cor.6.8\"></r>; c. acc. pers., <r v=\"1Cor.7.5\"></r>. Mid., <b>endure deprivation</b>: <r v=\"1Cor.6.7\"></r> (WM, § 38, 3; but v. Bl., § 54, 5; M, <i>Pr.</i>, 162); pass., <g>ἀπεστερημένοι</g>, <b>bereft of</b>: <r v=\"1Tim.6.5\"></r>.†</s>"},"G620":{"l":"ἀπολείπω","o":10,"ar":"<f><o>ἀπο-λείπω</o>،</f> <s n=\"1.\"><b>ترك</b>، <b>خلّف وراءه</b>: <r v=\"2Tim.4.13\"></r>، <r v=\"2Tim.4.20\"></r>، <r v=\"Titus.1.5\"></r>؛ المبني للمجهول: <b>بقي</b>، <b>تُرك (محفوظًا)</b>: <r v=\"Heb.4.6\"></r>، <r v=\"Heb.4.9\"></r> <r v=\"Heb.10.26\"></r>.</s> <s n=\"2.\"><b>هجر</b>، <b>ترك</b>: <r v=\"Jude.1.6\"></r>.†</s>","en":"<f><o>ἀπο-λείπω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2308\">חדל</h> <h n=\"H3498\">יתר</h>, etc.;]</e> </et> <s n=\"1.\"><b>to leave</b>, <b>leave behind</b> (in <g>π.</g> a <i>term. techn.</i> in wills; v. MM, s.v.): <r v=\"2Tim.4.13\"></r>, <r v=\"2Tim.4.20\"></r>, <r v=\"Titus.1.5\"></r>; pass., <b>to be reserved</b>, <b>remain</b>: <r v=\"Heb.4.6\"></r>, <r v=\"Heb.4.9\"></r> <r v=\"Heb.10.26\"></r>.</s> <s n=\"2.\"><b>to desert</b>, <b>abandon</b>: <r v=\"Jude.1.6\"></r>.†</s>"},"G639":{"l":"ἀπορέω","o":6,"ar":"<f><o>ἀπορέω</o>، <g>-ῶ</g></f> <s><b>تحيّر</b>، <b>ارتبك</b>: مطلقًا، <r v=\"Mark.6.20\"></r>؛ الصيغة الوسطى: <b>ارتاب</b>: مطلقًا، <r v=\"2Cor.4.8\"></r>؛ مع المنصوب، <r v=\"Acts.25.20\"></r>؛ يليه <g>περί</g>، <r v=\"Luke.24.4\"></r>؛ <g>ἐν</g>، <r v=\"Gal.4.20\"></r>؛ <g>περὶ τίνος λέγει</g>، <r v=\"John.13.22\"></r>.†</s>","en":"<f><o>ἀπορέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄπορος</g></x>, <g>ἀ-</g> neg., <x><g>πόρος</g></x>, <i>a way</i>, <i>resource</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6887\">צרר</h>, <h n=\"H4134\">מוּךְ</h>, etc.;]</e> </et> <s><b>to be at a loss</b>, <b>be perplexed</b>: absol., <r v=\"Mark.6.20\"></r> (<g>ἐποίει</g>, R, mg.); mid., <b>be in doubt</b>: absol., <r v=\"2Cor.4.8\"></r>; c. acc., <r v=\"Acts.25.20\"></r>; seq. <g>περί</g>, <r v=\"Luke.24.4\"></r>; <g>ἐν</g>, <r v=\"Gal.4.20\"></r>; <g>περὶ τίνος λέγει</g>, <r v=\"John.13.22\"></r>.†</s> <sy><i>SYN.</i>: <x><g>διαπορέω</g></x>, <x><g>διακρίνομαι</g></x>, <x><g>διστάζω</g></x>, <x><g>μετεωρίζομαι</g></x> (v. <i>DCG</i>, i, 491).</sy>"},"G635":{"l":"ἀποπλανάω","o":2,"ar":"<f><o>ἀπο-πλανάω</o>، <g>-ῶ</g>،</f> <s><b>أضلّ</b>؛ مجازيًا عن الإيقاع في الضلال: <r v=\"Mark.13.22\"></r>؛ المبني للمجهول: <b>ضلّ</b>: <r v=\"1Tim.6.10\"></r>.†</s>","en":"<f><o>ἀπο-πλανάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5080\">נדח</h> hi., <h n=\"H5186\">נטה</h> hi., <h n=\"H7725\">שׁוּב</h> pi.;]</e> </et> <s><b>to cause to go astray</b>; metaph., of leading into error: <r v=\"Mark.13.22\"></r>; pass., <b>to be led astray</b>: <r v=\"1Tim.6.10\"></r>.†</s>"},"G657":{"l":"ἀποτάσσω","o":6,"ar":"<f><o>ἀπο-τάσσω</o>،</f> <s><b>أفرز، خصّص</b>. الصيغة الوسطى، في اليونانية المتأخرة، مع القابل: <s n=\"(a)\"><b>ودّع</b>: <r v=\"Mark.6.46\"></r>، <r v=\"Luke.9.61\"></r>، <r v=\"Acts.18.18\"></r>، <r v=\"Acts.18.21\"></r>، <r v=\"2Cor.2.13\"></r>؛</s> <s n=\"(b)\"><b>ترك</b>: <r v=\"Luke.14.33\"></r>.†</s> </s>","en":"<f><o>ἀπο-τάσσω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Eccl.2.20\"></r> (<h n=\"H2976\">יאשׁ</h> pi.), <r v=\"1Esd.6.27\"></r>, <r v=\"Jer.20.2\"></r>, I Mac<i>4</i>*;]</e> </et> <s><b>to set apart</b>. Mid., in late Gk. (Bl., § 37, 1; Swete, <i>Mk.</i>, 136 f.; MM, s.v.), c. dat., <s n=\"(a)\"><b>to take leave of</b>: <r v=\"Mark.6.46\"></r>, <r v=\"Luke.9.61\"></r>, <r v=\"Acts.18.18\"></r>, <r v=\"Acts.18.21\"></r>, <r v=\"2Cor.2.13\"></r>;</s> <s n=\"(b)\"><b>to forsake</b>: <r v=\"Luke.14.33\"></r>.†</s> </s>"},"G699":{"l":"ἀρεσκία","o":1,"ar":"<f><o>ἀρεσκία</o>، <g>-ας, ἡ</g></f> <s><b>إرضاء</b>، <b>رغبة في الإرضاء</b>: <r v=\"Col.1.10\"></r>. (في اليونانية الكلاسيكية غالبًا بمعنى سيئ: التملّق.)†</s>","en":"<f><o>ἀρεσκία</o> (Rec. <g>-εία</g>), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀρέσκω</g></x>),</e> <e t=\"septuagint\">[in LXX (<g>-εία</g>): <r v=\"Prov.31.30\"></r> (<h n=\"H2580\">חֵן</h>)*;]</e> </et> <s><b>pleasing</b>, <b>desire to please</b>: <r v=\"Col.1.10\"></r>. In Gk. writers (Arist., Polyb.), most freq. in bad sense, but in <g>π.</g>, Inscr., and in Philo, as above (v. Deiss., <i>BS</i>, 224; MM, s.v.; Cremer, 642).†</s>"},"G665":{"l":"ἀποτρέπω","o":1,"ar":"<f>** <o>ἀπο-τρέπω</o>،</f> <s><b>صرف عن</b>؛ الصيغة الوسطى: <b>أعرض عن، تجنّب</b>: مع المنصوب، <r v=\"2Tim.3.5\"></r>.†</s>","en":"<f>** <o>ἀπο-τρέπω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.20.29\"></r> <r v=\"Sir.48.18\"></r>, <r v=\"3Macc.1.23\"></r>, <r v=\"4Macc.1.33\"></r> <r v=\"4Macc.16.12\"></r>*;]</e> </et> <s><b>to turn away</b>; mid., <b>to turn oneself away from</b>: c. acc., <r v=\"2Tim.3.5\"></r>.†</s>"},"G683":{"l":"ἀπωθέω","o":6,"ar":"<f><o>ἀπ-ωθέω</o>، <g>-ῶ</g>،</f> <s><b>يدفع بعيدًا</b>. والصيغة الوسطى: <b>يدفع عن نفسه</b>، <b>يرفض</b>، يطرح: مع المنصوب للشخص، <r v=\"Acts.7.27\"></r>، <r v=\"Acts.7.39\"></r>، <r v=\"Acts.13.46\"></r>، <r v=\"Rom.11.1\"></r>، <r v=\"Rom.11.2\"></r>، <r v=\"1Tim.1.19\"></r>.†</s>","en":"<f><o>ἀπ-ωθέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2186\">זנח</h>, <h n=\"H3988\">מאס</h>, etc.;]</e> </et> <s><b>to thrust away</b>. Mid., <b>to thrust away from oneself</b>, <b>refuse</b>, reject: c. acc. pers. (MM, s.v.), <r v=\"Acts.7.27\"></r>, <r v=\"Acts.7.39\"></r> <r v=\"Acts.13.46\"></r>, <r v=\"Rom.11.1\"></r>, <r v=\"Rom.11.2\"></r>, <r v=\"1Tim.1.19\"></r>.†</s>"},"G625":{"l":"Ἀπολλώς","o":10,"ar":"<f><o>Ἀπολλώς</o>، <g>-ώ, ὁ</g></f> <s><b>أبلّوس</b>: <r v=\"Acts.18.24\"></r>، <r v=\"Acts.19.1\"></r>، <r v=\"1Cor.1.12\"></r>، <r v=\"1Cor.3.4-1Cor.3.6\"></r>، <r v=\"1Cor.3.22\"></r>، <r v=\"1Cor.4.6\"></r>، <r v=\"1Cor.16.12\"></r>، <r v=\"Titus.3.13\"></r>.†</s>","en":"<f><o>Ἀπολλώς</o>, <g>-ώ, ὁ</g></f> <et> <e t=\"derivation\">(perh. contr. from <x><g>Ἀπολλώνιος</g></x>, <r v=\"Acts.18.24\"></r> D),</e> </et> <s><b>Apollos</b>: <r v=\"Acts.18.24\"></r> <r v=\"Acts.19.1\"></r>, <r v=\"1Cor.1.12\"></r> <r v=\"1Cor.3.4-1Cor.3.6\"></r>, <r v=\"1Cor.3.22\"></r> <r v=\"1Cor.4.6\"></r> <r v=\"1Cor.16.12\"></r>, <r v=\"Titus.3.13\"></r>.†</s>"},"G671":{"l":"ἀπόχρησις","o":1,"ar":"<f>*† <o>ἀπό-χρησις</o>، <g>-εως, ἡ</g></f> <s><b>استعمال</b> (بمعنى الاستهلاك والإفناء)، <b>سوء استعمال</b>: <r v=\"Col.2.22\"></r>.†</s>","en":"<f>*† <o>ἀπό-χρησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποχράομαι</g></x>,<i> to use to the full</i>, <i>abuse</i>),</e> </et> <s><b>abuse</b>, <b>misuse</b>: <r v=\"Col.2.22\"></r> (MM, s.v.).†</s>"},"G651":{"l":"ἀποστολή","o":5,"ar":"<f><o>ἀπο-στολή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>إرسال</b>، كإرسال حملة.</s> <s n=\"2.\">في السبعينية: <s n=\"(a)\"><b>صرف، إطلاق</b> (<r v=\"Eccl.8.8\"></r>)؛</s> <s n=\"(b)\"><b>هدية، عطية</b> (<r v=\"1Kgs.9.16\"></r>، <r v=\"1Macc.2.13\"></r>).</s> </s> <s n=\"3.\">في العهد الجديد: منصب رسول المسيح، <b>الرسولية</b>: <r v=\"Acts.1.25\"></r>، <r v=\"Rom.1.5\"></r>، <r v=\"1Cor.9.2\"></r>، <r v=\"Gal.2.8\"></r>.†</s>","en":"<f><o>ἀπο-στολή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποστέλλω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.22.7\"></r>, <r v=\"1Kgs.4.34\"></r> <r v=\"1Kgs.9.16\"></r>, <r v=\"Ps.78.49\"></r>, <r v=\"Eccl.8.8\"></r>, <r v=\"Song.4.13\"></r> (for <h n=\"H7971\">שׁלח</h> and its cognates), <r v=\"1Esd.9.51\"></r>, <r v=\"1Esd.9.54\"></r>, <r v=\"Jer.32.36\"></r>, <r v=\"Bar.2.25\"></r>, <r v=\"1Macc.2.18\"></r>, <r v=\"2Macc.3.2\"></r>*.]</e> </et> <s n=\"1.\">In cl., <b>a sending away</b> (MM, s.v.), as, an expedition (Hdt.).</s> <s n=\"2.\">In LXX <s n=\"(a)\"><b>discharge</b>, <b>dismissal</b> (<r v=\"Eccl.8.8\"></r>);</s> <s n=\"(b)\"><b>a gift</b> (<r v=\"1Kgs.9.16\"></r>, <r v=\"1Macc.2.13\"></r>).</s> </s> <s n=\"3.\">In NT, the office of an Apostle of Christ, <b>apostleship</b>: <r v=\"Acts.1.25\"></r>, <r v=\"Rom.1.5\"></r>, <r v=\"1Cor.9.2\"></r>, <r v=\"Gal.2.8\"></r> (Cremer, 530).†</s>"},"G684":{"l":"ἀπώλεια","o":18,"ar":"<f><o>ἀπώλεια</o>، <g>-ας, ἡ</g></f> <s><b>هلاك</b>، <b>إتلاف</b>، <b>خسارة</b>، <b>ضياع</b>: <r v=\"Matt.26.8\"></r>، <r v=\"Mark.14.4\"></r>، <r v=\"Acts.8.20\"></r>، <r v=\"Rom.9.22\"></r>، <r v=\"1Tim.6.9\"></r>، <r v=\"2Pet.2.1\"></r>؛ وبمعنى خاص عن خسارة الحياة الأبدية: <b>الهلاك</b>، عكس <g>σωτηρία</g>: <r v=\"Matt.7.13\"></r>، <r v=\"John.17.12\"></r>، <r v=\"Phil.1.28\"></r> <r v=\"Phil.3.19\"></r>، <r v=\"2Thess.2.3\"></r>، <r v=\"Heb.10.39\"></r>، <r v=\"2Pet.2.3\"></r> <r v=\"2Pet.3.7\"></r>، <r v=\"2Pet.3.16\"></r>، <r v=\"Rev.17.8\"></r>، <r v=\"Rev.17.11\"></r>.†</s>","en":"<f><o>ἀπώλεια</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπόλλυμι</g></x>),</e> <e t=\"septuagint\">[in LXX (Cremer, 797) for <h n=\"H6\">אבד</h>, <h n=\"H343\">אֵיד</h>, etc.;]</e> </et> <s><b>destruction</b>, <b>waste</b>, <b>loss</b>, <b>perishing</b> (in <g>π.</g>, of money, v. MM, s.v.): <r v=\"Matt.26.8\"></r>, <r v=\"Mark.14.4\"></r>, <r v=\"Acts.8.20\"></r>, <r v=\"Rom.9.22\"></r>, <r v=\"1Tim.6.9\"></r>, <r v=\"2Pet.2.1\"></r>; in special sense of the loss of eternal life, <b>perdition</b>, the antithesis of <g>σωτηρία</g>: <r v=\"Matt.7.13\"></r>, <r v=\"John.17.12\"></r>, <r v=\"Phil.1.28\"></r> <r v=\"Phil.3.19\"></r>, <r v=\"2Thess.2.3\"></r>, <r v=\"Heb.10.39\"></r>, <r v=\"2Pet.2.3\"></r> <r v=\"2Pet.3.7\"></r>, <r v=\"2Pet.3.16\"></r>, <r v=\"Rev.17.8\"></r>, <r v=\"Rev.17.11\"></r> (<i>DB</i>, iii, 744).†</s>"},"G692":{"l":"ἀργός","o":8,"ar":"<f><o>ἀργός</o>، <g>-όν</g></f> <s><b>عاطل</b>، <b>بطّال</b>: <r v=\"Matt.20.3\"></r>، <r v=\"Matt.20.6\"></r>، <r v=\"1Tim.5.13\"></r>، <r v=\"Titus.1.12\"></r>، <r v=\"2Pet.1.8\"></r>. مجازيًا، عن الأشياء: <b>عاطل</b>، <b>عديم الفعالية</b>، <b>عديم القيمة</b>: <g>ῥῆμα</g> (كلمة بطّالة)، <r v=\"Matt.12.36\"></r>؛ <g>πίστις</g> (إيمان)، <r v=\"Jas.2.20\"></r>.†</s>","en":"<f><o>ἀργός</o>, <g>-όν</g></f> <et> <e t=\"derivation\">(in late Gk., incl. NT, <g>-ή</g>, <g>-όν</g>; &lt; <g>ἀ-</g> neg., <x><g>ἔργον</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.6.7\"></r> (<h n=\"H4551\">מַסָּע</h>?), <r v=\"Wis.14.5\"></r> <r v=\"Wis.15.15\"></r>, <r v=\"Sir.37.11\"></r> <r v=\"Sir.38.28\"></r>*;]</e> </et> <s><b>inactive</b>, <b>idle</b>: <r v=\"Matt.20.3\"></r>, <r v=\"Matt.20.6\"></r>, <r v=\"1Tim.5.13\"></r>, <r v=\"Titus.1.12\"></r>, <r v=\"2Pet.1.8\"></r>. Metaph., of things, <b>inactive</b>, <b>ineffective</b>, <b>worthless</b>: <g>ῥῆμα</g>, <r v=\"Matt.12.36\"></r>; <g>πίστις</g>, <r v=\"Jas.2.20\"></r> (v. Cremer, 259 f.).†</s> <sy><i>SYN.</i>: <x><g>βραδύς</g></x>, <i>slow</i>; <x><g>νωθρός</g></x>, <i>sluggish</i> (Tr., <i>Syn.</i>, § civ).</sy>"},"G668":{"l":"ἀποφεύγω","o":3,"ar":"<f>** <o>ἀπο-φεύγω</o>،</f> <s><b>هرب من</b>، <b>نجا</b>: مع المنصوب، <r v=\"2Pet.2.18\"></r>، <r v=\"2Pet.2.20\"></r>؛ مع المضاف إليه، <r v=\"2Pet.1.4\"></r>.†</s>","en":"<f>** <o>ἀπο-φεύγω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.22.22\"></r>*;]</e> </et> <s><b>to flee from</b>, <b>escape</b>: c. acc., <r v=\"2Pet.2.18\"></r>, <r v=\"2Pet.2.20\"></r>; c. gen., <r v=\"2Pet.1.4\"></r>.†</s>"},"G644":{"l":"ἀποσκίασμα","o":1,"ar":"<f>*† <o>ἀπο-σκίασμα</o>، <g>-τος, τό</g></f> <s><b>ظل</b>: <r v=\"Jas.1.17\"></r>.†</s>","en":"<f>*† <o>ἀπο-σκίασμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποσκιάζω</g></x>, <i>to cast a shadow</i>; v.s. <x><g>σκία</g></x>),</e> </et> <s><b>a shadow</b>: <r v=\"Jas.1.17\"></r> (MM, s.v.).†</s>"},"G691":{"l":"ἀργέω","o":1,"ar":"<f><o>ἀργέω</o>، <g>-ῶ</g></f> <s><b>كان عاطلاً، توانى</b>؛ <g>τὸ κρίμα . . . ἀ.</g>، <b>يتوانى</b>: <r v=\"2Pet.2.3\"></r>.†</s>","en":"<f><o>ἀργέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀργός</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.4.24\"></r>, <r v=\"Eccl.12.3\"></r> (<h n=\"H988\">בּטל</h>), <r v=\"1Esd.2.30\"></r>, <r v=\"Sir.30.36\"></r> (<r v=\"Sir.33.27\"></r>), <r v=\"2Macc.5.25\"></r>*;]</e> </et> <s><b>to be idle</b>; <g>τὸ κρίμα . . . ἀ.</g>, <b>lingers</b> (cf. MGr. <g>ἀργά</g>, <b>late</b>: MM, s.v.): <r v=\"2Pet.2.3\"></r>.†</s>"},"G600":{"l":"ἀποκαθίστημι","o":8,"ar":"<f> <o>ἀπο-καθ-ίστημι</o> (<x><g>ἀποκαθιστάω</g></x>، <r v=\"Mark.9.12\"></r>؛ <g>-ιστάνω</g>، <r v=\"Acts.1.6\"></r>)،</f> <s n=\"1.\"><b>ردّ، أعاد</b>، أي إلى حالة سابقة: عن الصحة، <r v=\"Matt.12.13\"></r>، <r v=\"Mark.3.5\"></r> <r v=\"Mark.8.25\"></r>، <r v=\"Luke.6.10\"></r>؛ عن الشؤون الاجتماعية أو السياسية، <r v=\"Matt.17.11\"></r>، <r v=\"Mark.9.12\"></r>، <r v=\"Acts.1.6\"></r>.</s> <s n=\"2.\"><b>ردّ، أرجع</b>: <r v=\"Heb.13.19\"></r>.†</s>","en":"<f> <o>ἀπο-καθ-ίστημι</o> (<x><g>ἀποκαθιστάω</g></x>, <r v=\"Mark.9.12\"></r>, Rec., <g>-ιστάνω</g>, LTTr.; cf. <r v=\"Acts.1.6\"></r>; <g>-κατιστάνω</g>, WH),</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7725\">שׁוּב</h> ;] </e> </et> <s n=\"1.\"><b>to restore</b>, i.e. to a former condition: of health, <r v=\"Matt.12.13\"></r>, <r v=\"Mark.3.5\"></r> <r v=\"Mark.8.25\"></r>, <r v=\"Luke.6.10\"></r>; of social or political affairs, <r v=\"Matt.17.11\"></r>, <r v=\"Mark.9.12\"></r>, <r v=\"Acts.1.6\"></r>.</s> <s n=\"2.\"><b>to give back</b>, <b>bring back</b>: <r v=\"Heb.13.19\"></r> (so in <g>π.</g>, MM, s.v.; cf. also Cremer, 312).†</s>"},"G658":{"l":"ἀποτελέω","o":2,"ar":"<f>** <o>ἀπο-τελέω</o>، <g>-ῶ </g></f> <s><b>أنهى</b>، <b>أكمل</b>، <b>أتمّ</b>: <r v=\"Luke.13.32\"></r>، <r v=\"Jas.1.15\"></r>.†</s>","en":"<f>** <o>ἀπο-τελέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.5.73\"></r>, <r v=\"1Macc.15.39\"></r>*;]</e> </et> <s><b>to bring to an end</b>, <b>complete</b>, <b>accomplish</b> (cf. MM, s.v.): <r v=\"Luke.13.32\"></r>, <r v=\"Jas.1.15\"></r>.†</s>"},"G616":{"l":"ἀποκυέω","o":2,"ar":"<f>** <o>ἀπο-κυέω</o>، <g>-ῶ</g></f> <s>أصلاً، «اللفظ الطبي للولادة بوصفها ختام الحمل». وفي <g>κοινή</g> هو «مرادف عادي لـ <x><g>τίκτω</g></x>، غير أن <g>ἀπό</g> يجعله دالاً على الإتمام، فيفيد الولادة السالمة»: <b>ولد</b>، <b>أنجب</b>: <r v=\"Jas.1.15\"></r>، <r v=\"Jas.1.18\"></r>.†</s>","en":"<f>** <o>ἀπο-κυέω</o> (Rec. <g>-κύω</g>), <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπό</g></x>, <x><g>κυέω</g></x> or <x><g>κύω</g></x>, <i>to be pregnant</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.15.17\"></r>*;]</e> </et> <s>prop., \"the medical word for birth as the close of pregnancy\" (Hort, <i>Ja.</i>, 26 f.). In <g>κοινή</g>, \"an ordinary syn. of <x><g>τίκτω</g></x>, but definitely 'perfectivised' (M, <i>Pr.</i>, 111 ff.; MM, s.v.) by the <g>ἀπό</g>, and so implying safe delivery,\" <b>to bring forth</b>, <b>give birth to</b>: <r v=\"Jas.1.15\"></r>, <r v=\"Jas.1.18\"></r>.†</s>"},"G623":{"l":"Ἀπολλύων","o":1,"ar":"<f><o>Ἀπολλύων</o>، <g>-οντος, ὁ</g></f> <s><b>أبوليون</b>، أي المُهلِك: <r v=\"Rev.9.11\"></r> (قارن <x><g>Ἀβάδδων</g></x>).†</s>","en":"<f><o>Ἀπολλύων</o>, <g>-οντος, ὁ</g></f> <et> <e t=\"derivation\">(pres. ptcp. of <x><g>ἀπολλύω</g></x>),</e> </et> <s><b>Apollyon</b>, i.e. the Destroyer: <r v=\"Rev.9.11\"></r> (cf. <x><g>Ἀβάδδων</g></x>). (Cremer, 453; <i>DB</i>, i, 125, 172.)†</s>"},"G694":{"l":"ἀργύριον","o":20,"ar":"<f><o>ἀργύριον</o>، <g>-ου, τό</g></f> <s>أصلاً: <b>قطعة من الفضة</b>؛ وفي العهد الجديد: <s n=\"(a)\"><b>فضة</b>: <r v=\"Acts.3.6\"></r> <r v=\"Acts.7.16\"></r> <r v=\"Acts.19.19\"></r> <r v=\"Acts.20.33\"></r>، <r v=\"1Cor.3.12\"></r>، <r v=\"1Pet.1.18\"></r>؛</s> <s n=\"(b)\"><b>مال، دراهم</b>: <r v=\"Matt.25.18\"></r>، <r v=\"Matt.25.27\"></r>، <r v=\"Mark.14.11\"></r>، <r v=\"Luke.9.3\"></r> <r v=\"Luke.19.15\"></r>، <r v=\"Luke.19.23\"></r> <r v=\"Luke.22.5\"></r>، <r v=\"Acts.8.20\"></r>؛</s> <s n=\"(c)\"><b>قطعة نقود فضية</b>: في الجمع، <r v=\"Matt.26.15\"></r> <r v=\"Matt.27.3\"></r>، <r v=\"Matt.27.5\"></r>، <r v=\"Matt.27.6\"></r>، <r v=\"Matt.27.9\"></r> <r v=\"Matt.28.12\"></r>، <r v=\"Matt.28.15\"></r>، حيث قيمتها قيمة الشاقل أو رباعي الدراهم؛ <g>ἀργυρίου μυριάδες πέντε</g> (والأرجح أنها دراهم)، <r v=\"Acts.19.19\"></r>.†</s> </s>","en":"<f><o>ἀργύριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄργυρος</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3701\">כֶּסֶף</h> (<r v=\"Gen.13.2\"></r>, al.), exc. <r v=\"Lam.4.1\"></r> (<h n=\"H3800\">כֶּתֶם</h>);]</e> </et> <s>prop., <b>a piece of silver</b> (Lft., <i>Notes</i>, 191); in NT, <s n=\"(a)\"><b>silver</b>: <r v=\"Acts.3.6\"></r> <r v=\"Acts.7.16\"></r> <r v=\"Acts.19.19\"></r> <r v=\"Acts.20.33\"></r>, <r v=\"1Cor.3.12\"></r>, <r v=\"1Pet.1.18\"></r>;</s> <s n=\"(b)\"><b>money</b>: <r v=\"Matt.25.18\"></r>, <r v=\"Matt.25.27\"></r>, <r v=\"Mark.14.11\"></r>, <r v=\"Luke.9.3\"></r> <r v=\"Luke.19.15\"></r>, <r v=\"Luke.19.23\"></r> <r v=\"Luke.22.5\"></r>, <r v=\"Acts.8.20\"></r>;</s> <s n=\"(c)\"><b>a silver coin</b>: pl., <r v=\"Matt.26.15\"></r> <r v=\"Matt.27.3\"></r>, <r v=\"Matt.27.5\"></r>, <r v=\"Matt.27.6\"></r>, <r v=\"Matt.27.9\"></r> <r v=\"Matt.28.12\"></r>, <r v=\"Matt.28.15\"></r>, where the value is that of a shekel or tetradrachm; <g>ἀργυρίου μυριάδες πέντε</g> (prob. drachmas; MM, s.v.), <r v=\"Acts.19.19\"></r>.†</s> </s>"},"G673":{"l":"ἀποχωρίζω","o":2,"ar":"<f><o>ἀπο-χωρίζω</o>،</f> <s><b>فصل</b>، <b>فرّق</b>: المبني للمجهول، <r v=\"Rev.6.14\"></r>؛ وانعكاسيًا: <b>انفصل</b>: <r v=\"Acts.15.39\"></r>.†</s>","en":"<f><o>ἀπο-χωρίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.43.21\"></r> (<h n=\"H4662\">מִפְקָד</h>)*;]</e> </et> <s><b>to separate</b>, <b>part asunder</b>: pass., <r v=\"Rev.6.14\"></r>; reflexively, <b>to separate oneself</b>: <r v=\"Acts.15.39\"></r>.†</s>"},"G678":{"l":"ἀπροσωπολήμπτως","o":1,"ar":"<f>*† <o>ἀπροσωπολήμπτως</o>،</f> ظرف <s><b>بغير محاباة</b>، <b>بلا تحيّز</b>: <r v=\"1Pet.1.17\"></r>.†</s>","en":"<f>*† <o>ἀπροσωπολήμπτως</o> (Rec. <g>-λήπτως</g>, cl.),</f> adv. <et> <e t=\"derivation\">(&lt; <g>α-</g> neg., <x><g>προσωπολήμπτης</g></x>),</e> </et> <s><b>without respect of persons</b>, <b>impartially</b>: <r v=\"1Pet.1.17\"></r>.†</s>"},"G679":{"l":"ἄπταιστος","o":1,"ar":"<f>** <o>ἄ-πταιστος</o>، <g>-ον</g></f> <s><b>بلا عثرة</b>، <b>ثابت القدم</b>: مجازيًا، <r v=\"Jude.1.24\"></r>.†</s>","en":"<f>** <o>ἄ-πταιστος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>πταίω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.6.39\"></r>*;]</e> </et> <s><b>without stumbling</b>, <b>sure-footed</b>: metaph. (MM, s.v.), <r v=\"Jude.1.24\"></r>.†</s>"},"G630":{"l":"ἀπολύω","o":64,"ar":"<f><o>ἀπο-λύω</o>،</f> <s n=\"1.\"><b>أطلق</b>، <b>حرّر</b>: <r v=\"Luke.13.12\"></r>، <r v=\"John.19.10\"></r>، وفي مواضع أخرى؛ عن المدين، <r v=\"Matt.18.27\"></r>؛ مجازيًا عن الغفران، <r v=\"Luke.6.37\"></r>.</s> <s n=\"2.\"><b>صرف</b>، <b>أطلق</b> (سمح بالانصراف): <r v=\"Matt.15.23\"></r>، <r v=\"Luke.2.29\"></r>، <r v=\"Luke.9.12\"></r>، <r v=\"Acts.19.41\"></r>، وفي مواضع أخرى؛ عن الطلاق، <g>τ. γυναῖκα</g>: <r v=\"Matt.1.19\"></r>، <r v=\"Matt.5.31\"></r>، <r v=\"Matt.5.32\"></r>، <r v=\"Matt.19.3\"></r>، <r v=\"Matt.19.8\"></r>، <r v=\"Matt.19.9\"></r>، <r v=\"Mark.10.2\"></r>، <r v=\"Mark.10.4\"></r>، <r v=\"Mark.10.11\"></r>، <r v=\"Luke.16.18\"></r>؛ وإشارةً إلى العادة اليونانية والرومانية (لا اليهودية)، <g>τ. ἄνδρα</g>: <r v=\"Mark.10.12\"></r>. الصيغة الوسطى، <b>انصرف، رحل</b>: <r v=\"Acts.28.25\"></r>.</s>","en":"<f><o>ἀπο-λύω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7725\">שׁוּב</h>, etc., freq. in I-IV Mac;]</e> </et> <s n=\"1.\"><b>to set free</b>, <b>release</b>: <r v=\"Luke.13.12\"></r>, <r v=\"John.19.10\"></r>, al.; a debtor, <r v=\"Matt.18.27\"></r>; metaph., of forgiveness, <r v=\"Luke.6.37\"></r>.</s> <s n=\"2.\"><b>to let go</b>, <b>dismiss</b> (Field, <i>Notes</i>, 9 f.): <r v=\"Matt.15.23\"></r>, <r v=\"Luke.2.29\"></r> <r v=\"Luke.9.12\"></r>, <r v=\"Acts.19.41\"></r>, al.; of divorce, <g>τ. γυναῖκα</g>: <r v=\"Matt.1.19\"></r> <r v=\"Matt.5.31\"></r>, <r v=\"Matt.5.32\"></r> <r v=\"Matt.19.3\"></r>, <r v=\"Matt.19.8\"></r>, <r v=\"Matt.19.9\"></r>, <r v=\"Mark.10.2\"></r>, <r v=\"Mark.10.4\"></r>, <r v=\"Mark.10.11\"></r>, <r v=\"Luke.16.18\"></r>; with ref. to Gk. and Rom. (net Jewish) custom, <g>τ. ἄνδρα</g>: <r v=\"Mark.10.12\"></r>. Mid., <b>to depart</b>: <r v=\"Acts.28.25\"></r> (MM, s.v.).</s>"},"G632":{"l":"ἀπονέμω","o":1,"ar":"<f><o>ἀπο-νέμω</o></f> <s><b>أعطى، أوفى</b>، <b>خصّص، قسم</b>: <r v=\"1Pet.3.7\"></r>.†</s>","en":"<f><o>ἀπο-νέμω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>νέμω</g></x>, <i>to distribute</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.4.19\"></r> (<h n=\"H2505\">חלק</h>), <r v=\"3Macc.1.7\"></r> <r v=\"3Macc.3.16\"></r>*;]</e> </et> <s><b>to assign</b>, <b>apportion</b>: <r v=\"1Pet.3.7\"></r>. (In <g>π.</g> of a Prefect who renders to all their dues; v. MM, s.v.)†</s>"},"G645":{"l":"ἀποσπάω","o":5,"ar":"<f><o>ἀπο-σπάω</o>، <g>-ῶ</g>،</f> <s><b>جذب بعيدًا</b> أو <b>أبعد</b>، <b>انتزع</b>: <r v=\"Acts.20.30\"></r>؛ <g>μάχαιραν</g>، استلَّ سيفًا، <r v=\"Matt.26.51\"></r>؛ المبني للمجهول، <b>انفصل</b> أو <b>ابتعد</b>، <r v=\"Luke.22.41\"></r>، <r v=\"Acts.21.1\"></r>.†</s>","en":"<f><o>ἀπο-σπάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5423\">נתק</h>: ni., hi., etc.;]</e> </et> <s><b>to draw off</b> or <b>away</b>, <b>tear away</b> (MM, s.v.): <r v=\"Acts.20.30\"></r>; <g>μάχαιραν</g>, draw a sword, <r v=\"Matt.26.51\"></r>; pass., <b>to be parted</b> or <b>withdrawn</b> (Field, <i>Notes</i>, 134; but v. Thayer, s.v.), <r v=\"Luke.22.41\"></r>, <r v=\"Acts.21.1\"></r>.†</s>"},"G669":{"l":"ἀποφθέγγομαι","o":3,"ar":"<f>† <o>ἀπο-φθέγγομαι</o>،</f> <s><b>نطق</b>، <b>تكلَّم بوضوح</b>: <r v=\"Acts.2.4\"></r>، <r v=\"Acts.2.14\"></r>، <r v=\"Acts.26.25\"></r>.†</s>","en":"<f>† <o>ἀπο-φθέγγομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5012\">נבא</h>, etc.;]</e> </et> <s><b>to speak forth</b>, <b>give utterance</b>: <r v=\"Acts.2.4\"></r>, <r v=\"Acts.2.14\"></r> <r v=\"Acts.26.25\"></r> (MM, s.v.).†</s>"},"G631":{"l":"ἀπομάσσω","o":1,"ar":"<f>** <o>ἀπο-μάσσω</o></f> <s><b>مسح</b>، <b>نفض</b>: الصيغة الوسطى، <r v=\"Luke.10.11\"></r>.†</s>","en":"<f>** <o>ἀπο-μάσσω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>μάσσω</g></x>, Att. <g>-ττω</g>, <i>to touch</i>, <i>handle</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Tob.7.17\"></r>*;]</e> </et> <s><b>to wipe off</b>, <b>wipe clean</b>: mid., <r v=\"Luke.10.11\"></r>.†</s>"},"G689":{"l":"Ἀράμ","o":2,"ar":"<f><o>Ἀράμ</o> لا يُصرَّف (العبرية <h n=\"H7410\">רָם</h>)،</f> <s><b>أرام</b>: <r v=\"Matt.1.3\"></r>، <r v=\"Matt.1.4\"></r>، <r v=\"Luke.3.33\"></r>.†</s>","en":"<f><o>Ἀράμ</o> indec. (Heb. <h n=\"H7410\">רָם</h>),</f> <s><b>Aram</b>: <r v=\"Matt.1.3\"></r>, <r v=\"Matt.1.4\"></r>, <r v=\"Luke.3.33\"></r> (R, txt., WH, <g>Ἀρνεί</g>).†</s>"},"G698":{"l":"Ἀρεοπαγίτης","o":1,"ar":"<f><o>Ἀρεοπαγίτης</o>، <g>-ου, ὁ</g>، </f> <s>قاضٍ في محكمة أريوس باغوس، <b>أريوباغي</b>: <r v=\"Acts.17.34\"></r>.†</s>","en":"<f><o>Ἀρεοπαγίτης</o> (T, <g>-είτης</g>), <g>-ου, ὁ</g> (v. supr.), </f> <s>a judge of the Court of Areopagus: <r v=\"Acts.17.34\"></r>.†</s>"},"G608":{"l":"ἀποκλείω","o":1,"ar":"<f><o>ἀπο-κλείω</o>،</f> <s><b>أغلق بإحكام</b>: <r v=\"Luke.13.25\"></r>.†</s>","en":"<f><o>ἀπο-κλείω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5462\">סגר</h>;]</e> </et> <s><b>to shut fast</b>: <r v=\"Luke.13.25\"></r>.†</s>"},"G617":{"l":"ἀποκυλίω","o":4,"ar":"<f>† <o>ἀπο-κυλίω</o></f> <s><b>يُدحرج</b>: <r v=\"Matt.28.2\"></r>، <r v=\"Mark.16.3\"></r>، <r v=\"Luke.24.2\"></r>.†</s>","en":"<f>† <o>ἀπο-κυλίω</o></f> <et> <e t=\"derivation\">(v.s. <x><g>κυλίω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.29.3\"></r>, <r v=\"Gen.29.8\"></r>, <r v=\"Gen.29.10\"></r> (<h n=\"H1556\">גּלל</h>) <r v=\"Jdt.13.9\"></r>*;]</e> </et> <s><b>to roll away</b>: <r v=\"Matt.28.2\"></r>, <r v=\"Mark.16.3\"></r>, <r v=\"Luke.24.2\"></r>.†</s>"},"G690":{"l":"Ἄραψ","o":1,"ar":"<f><o>Ἄραψ</o>، <g>-αβος, ὁ</g>،</f> <s><b>عربي</b>: <r v=\"Acts.2.11\"></r>.†</s>","en":"<f><o>Ἄραψ</o>, <g>-αβος, ὁ</g>,</f> <s><b>an Arabian</b>: <r v=\"Acts.2.11\"></r>.†</s>"},"G653":{"l":"ἀποστοματίζω","o":1,"ar":"<f>* <o>ἀποστοματίζω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>تكلّم من الذاكرة</b>، <b>أملى</b> على تلميذ.</s> <s n=\"2.\">في اليونانية المتأخرة: <b>استنطق</b>، <b>سأل</b>: <r v=\"Luke.11.53\"></r>.†</s>","en":"<f>* <o>ἀποστοματίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>στόμα</g></x>),</e> </et> <s n=\"1.\">In cl., <b>to speak from memory</b>, <b>to dictate</b> to a pupil (Plat.).</s> <s n=\"2.\">In late Gk., <b>to catechize</b>, <b>question</b>: <r v=\"Luke.11.53\"></r> (MM, s.v.).†</s>"},"G636":{"l":"ἀποπλέω","o":6,"ar":"<f>* <o>ἀπο-πλέω</o>، <g>-ῶ</g>،</f> <s><b>سافر بحرًا، أقلع</b>: <r v=\"Acts.13.4\"></r> <r v=\"Acts.14.26\"></r> <r v=\"Acts.20.15\"></r> <r v=\"Acts.27.1\"></r>.†</s>","en":"<f>* <o>ἀπο-πλέω</o>, <g>-ῶ</g>,</f> <s><b>to sail away</b>: <r v=\"Acts.13.4\"></r> <r v=\"Acts.14.26\"></r> <r v=\"Acts.20.15\"></r> <r v=\"Acts.27.1\"></r> (Burton, 159).†</s>"},"G605":{"l":"ἀποκατάστασις","o":1,"ar":"<f>* <o>ἀπο-κατά-στασις</o>، <g>-εως, ἡ</g></f> <s><b>ردّ، إصلاح، استعادة</b>: <r v=\"Acts.3.21\"></r>.†</s>","en":"<f>* <o>ἀπο-κατά-στασις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποκαθίστημι</g></x>),</e> </et> <s><b>restoration</b>: <r v=\"Acts.3.21\"></r> (in <g>π.</g> of repairs and restorations of temples, v. MM, s.v.).†</s>"},"G660":{"l":"ἀποτινάσσω","o":2,"ar":"<f><o>ἀπο-τινάσσω</o>،</f> <s><b>نفض</b>: <r v=\"Luke.9.5\"></r>، <r v=\"Acts.28.5\"></r>.†</s>","en":"<f><o>ἀπο-τινάσσω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.16.20\"></r> A (<h n=\"H5287\">נער</h> ni.), <r v=\"1Sam.10.2\"></r> (<h n=\"H5203\">נטשׁ</h>), <r v=\"Lam.2.7\"></r> (<h n=\"H5010\">נאר</h> pi.)*;]</e> </et> <s><b>to shake of</b>: <r v=\"Luke.9.5\"></r>, <r v=\"Acts.28.5\"></r>.†</s>"},"G697":{"l":"Ἄρειος_Πάγος","o":null,"ar":"<f><o>Ἄρειος Πάγος</o>، <g>-ου, ὁ</g>،</f> <s><b>تل أريس</b> أو <b>مريخ</b>، <b>أريوس باغوس</b>؛ وأيضًا <b>مجلس أريوس باغوس</b>، أعلى محكمة في أثينا: <r v=\"Acts.17.19\"></r>، <r v=\"Acts.17.22\"></r>.†</s>","en":"<f><o>Ἄρειος Πάγος</o> (T, <g>Ἄριος Π.</g>), <g>-ου, ὁ</g>,</f> <s><b>Hill of Ares</b> or <b>Mars</b>, <b>Areopagus</b>; also, <b>the Court of Areopagus</b>, the highest tribunal of Athens: <r v=\"Acts.17.19\"></r>, <r v=\"Acts.17.22\"></r>.†</s>"},"G612":{"l":"ἀπόκρισις","o":4,"ar":"<f><o>ἀπό-κρισις</o>، <g>-εως, ἡ</g></f> <s><b>إجابة</b>، <b>جواب</b>: <r v=\"Luke.2.47\"></r>، <r v=\"Luke.20.26\"></r>، <r v=\"John.1.22\"></r>، <r v=\"John.19.9\"></r>.†</s>","en":"<f><o>ἀπό-κρισις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀποκρίνομαι</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H1697\">דּבר</h>, etc.;]</e> </et> <s><b>an answering</b>, <b>an answer</b>: <r v=\"Luke.2.47\"></r> <r v=\"Luke.20.26\"></r>, <r v=\"John.1.22\"></r> <r v=\"John.19.9\"></r>.†</s>"},"G675":{"l":"Ἄππιος","o":1,"ar":"<f><o>Ἄππιος</o>، <g>-ου, ὁ</g>،</f> <s><b>أبيوس</b>؛ <g>Ἀππίου Φόρον</g>، <l>Appii Forum</l> (سوق أبيوس)، بلدة في إيطاليا: <r v=\"Acts.28.15\"></r>.†</s>","en":"<f><o>Ἄππιος</o>, <g>-ου, ὁ</g>,</f> <s><b>Appius</b>; <g>Ἀππίου Φόρον</g>, <l>Appii Forum</l> (Market of Appius), a town in Italy: <r v=\"Acts.28.15\"></r>.†</s>"},"G624":{"l":"Ἀπολλωνία","o":1,"ar":"<f><o>Ἀπολλωνία</o>، <g>-ας, ἡ</g>،</f> <s><b>أبولونية</b>، مدينة في مكدونية: <r v=\"Acts.17.1\"></r>.†</s>","en":"<f><o>Ἀπολλωνία</o>, <g>-ας, ἡ</g>,</f> <s><b>Apollonia</b>, a city of Macedonia: <r v=\"Acts.17.1\"></r>.†</s>"},"G637":{"l":"ἀποπλύνω","o":1,"ar":"<f><o>ἀπο-πλύνω</o>،</f> <s><b>غسل وأزال</b>: قراءة بديلة لـ <g>πλύνω</g>، <r v=\"Luke.5.2\"></r>.†</s>","en":"<f><o>ἀπο-πλύνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3526\">כּבס</h> pi.;]</e> </et> <s><b>to wash off</b>: v.l. for <g>πλύνω</g>, <r v=\"Luke.5.2\"></r>, Rec.†</s>"},"G672":{"l":"ἀποχωρέω","o":5,"ar":"<f><o>ἀπο-χωρέω</o>، <g>-ῶ</g>،</f> <s><b>انصرف</b>، <b>ذهب</b>، <b>تنحّى</b>: يليه <g>ἀπό</g>، <r v=\"Matt.7.23\"></r>، <r v=\"Luke.9.39\"></r>، <r v=\"Acts.13.13\"></r> (وقارن مطلقًا، <r v=\"Luke.20.20\"></r>).†</s>","en":"<f><o>ἀπο-χωρέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.46.5\"></r> (<h n=\"H5472\">סוּג</h>), <r v=\"2Macc.4.33\"></r>, <r v=\"3Macc.2.33\"></r>*;]</e> </et> <s><b>to go away</b>, <b>depart</b>, <b>withdraw</b>: seq. <g>ἀπό</g>, <r v=\"Matt.7.23\"></r>, <r v=\"Luke.9.39\"></r>, <r v=\"Acts.13.13\"></r> (absol., <r v=\"Luke.20.20\"></r>, Tr., mg.).†</s>"},"G670":{"l":"ἀποφορτίζομαι","o":1,"ar":"<f>*† <o>ἀπο-φορτίζομαι</o></f> <s><b>أفرغ الحمولة</b>، <b>أنزل الوَسْق</b>: مع المنصوب، <g>τ. γόμον</g>، <r v=\"Acts.21.3\"></r>.†</s>","en":"<f>*† <o>ἀπο-φορτίζομαι</o></f> <et> <e t=\"derivation\">(&lt; <x><g>φορτίζω</g></x>, <i>to load</i>),</e> </et> <s><b>to discharge a cargo</b> (Field, <i>Notes</i>, 134), <b>to unlade</b>: c. acc., <g>τ. γόμον</g>, <r v=\"Acts.21.3\"></r>.†</s>"},"G621":{"l":"ἀπολείχω","o":1,"ar":"<f>† <o>ἀπο-λείχω</o></f> <s><b>لحس</b>: <r v=\"Luke.16.21\"></r>، في النص المستلَم.†</s>","en":"<f>† <o>ἀπο-λείχω</o></f> <et> <e t=\"derivation\">(for <g>ἐπιλ-</g>, q.v.),</e> </et> <s><b>to lick up</b>: <r v=\"Luke.16.21\"></r>, Rec.†</s>"},"G648":{"l":"ἀποστεγάζω","o":1,"ar":"<f>** <o>ἀπο-στεγάζω</o></f> <s><b>كشف السقف</b>: <r v=\"Mark.2.4\"></r>.†</s>","en":"<f>** <o>ἀπο-στεγάζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>στέγη</g></x>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Jer.49.10\"></r> (<r v=\"Jer.29.11\"></r>)*;]</e> </et> <s><b>to unroof</b>: <r v=\"Mark.2.4\"></r>.†</s>"},"G681":{"l":"ἅπτω","o":39,"ar":"<f><o>ἅπτω</o>،</f> <s>أصلاً، <b>ربط بـ، ألصق بـ</b>؛ ومن ثمّ، عن النار، <b>أشعل</b>، <b>أوقد</b>: <r v=\"Luke.8.16\"></r> <r v=\"Luke.11.33\"></r> <r v=\"Luke.15.8\"></r>، <r v=\"Acts.28.2\"></r>. الصيغة الوسطى، مع المضاف إليه، <b>تعلّق بـ</b>، <b>التصق بـ</b>، <b>أمسك بـ، لمس</b>: <r v=\"Matt.8.3\"></r>، <r v=\"Matt.8.15\"></r>، <r v=\"John.20.17\"></r>، وفي مواضع أخرى؛ عن المعاشرة الجسدية، <r v=\"1Cor.7.1\"></r>؛ إشارةً إلى المحظورات اللاوية والطقسية، <r v=\"2Cor.6.17\"></r>، <r v=\"Col.2.21\"></r>؛ عن الفعل العدائي، <r v=\"1John.5.18\"></r> (قارن <g>ἀν-</g>، <g>καθ-</g>، <g>περι-</g> <g>άπτω</g>).</s>","en":"<f><o>ἅπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5060\">נגע</h>;]</e> </et> <s>prop., <b>to fasten to</b>; hence, of fire, <b>to kindle</b>, <b>light</b>: <r v=\"Luke.8.16\"></r> <r v=\"Luke.11.33\"></r> <r v=\"Luke.15.8\"></r>, <r v=\"Acts.28.2\"></r>. Mid., c. gen., <b>to fasten oneself to</b>, <b>cling to</b>, <b>lay hold of</b> (so in <g>π.</g>; MM, s.v.): <r v=\"Matt.8.3\"></r>, <r v=\"Matt.8.15\"></r>, <r v=\"John.20.17\"></r>, al.; of carnal intercourse, <r v=\"1Cor.7.1\"></r>; with reference to levitical and ceremonial prohibitions, <r v=\"2Cor.6.17\"></r>, <r v=\"Col.2.21\"></r>; of hostile action, <r v=\"1John.5.18\"></r> (cf. <g>ἀν-</g>, <g>καθ-</g>, <g>περι-</g> <g>άπτω</g>).</s> <sy><i>SYN.</i>: <x><g>θιγγάνω</g></x>, <x><g>ψηλαφάω</g></x>. <g>ἅ.</g> is the stronger, <g>θ.</g>, <i>to touch</i>, the lighter term. <g>ψ.</g> is <i>to feel</i>, as in search of something (Tr., <i>Syn.</i>, § xvii; Lft., <i>Col.</i>, 201 f.).</sy>"},"G656":{"l":"ἀποσυνάγωγος","o":3,"ar":"<f>*† <o>ἀποσυνάγωγος</o>، <g>-ον</g></f> <s><b>مطرود من المجمع</b>، <b>محروم (من الشركة)</b>: <r v=\"John.9.22\"></r> <r v=\"John.12.42\"></r> <r v=\"John.16.2\"></r>.†</s>","en":"<f>*† <o>ἀποσυνάγωγος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>συναγωγή</g></x>),</e> </et> <s><b>expelled from the congregation</b> (Field, <i>Notes</i>, 96), <b>excommunicated</b>: <r v=\"John.9.22\"></r> <r v=\"John.12.42\"></r> <r v=\"John.16.2\"></r> (Cremer, 64, 607).†</s>"},"G647":{"l":"ἀποστάσιον","o":3,"ar":"<f><o>ἀποστάσιον</o>، <g>-ου, τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: فقط في عبارة <g>ἀποστασίου δίκη</g>، أي دعوى تُقام على عبدٍ مُعتَق لتخلّيه عن <g>προστάτης</g>.</s> <s n=\"2.\">في السبعينية، <g>βιβλίον ἀποστασίου</g>، <b>كتاب طلاق</b>: <r v=\"Matt.19.7\"></r>، <r v=\"Mark.10.4\"></r>؛ وبالمعنى نفسه <g>ἀ.</g> وحدها، <r v=\"Matt.5.31\"></r>.†</s>","en":"<f><o>ἀποστάσιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀφίστημι</g></x>),</e> <e t=\"septuagint\">[in LXX; <r v=\"Deut.24.1\"></r>, <r v=\"Deut.24.3\"></r>, <r v=\"Jer.3.8\"></r>, <r v=\"Isa.50.1\"></r> (<h n=\"H3748\">כְּרִיתֻת</h>, <h n=\"H3748\">כְּרִיתוּת</h>)*;]</e> </et> <s n=\"1.\">in cl., only in phrase <g>ἀποστασίου δίκη</g>, an action against a freedman for forsaking his <g>προστάτης</g> (Dem.).</s> <s n=\"2.\">In LXX, <g>βιβλίον ἀποστασίου</g>, <b>a bill of divorce</b>: <r v=\"Matt.19.7\"></r>, <r v=\"Mark.10.4\"></r>; in same sense <g>ἀ.</g> alone (MM, s.v.), <r v=\"Matt.5.31\"></r> (for other late exx., v. MM, s.v.; Kennedy, <i>Sources</i>, 121).†</s>"},"G687":{"l":"ἆρα","o":18,"ar":"<f><o>ἆρα</o>،</f> أداة استفهام، تدل على القلق أو نفاد الصبر، وهي نادرة ولا ترد إلا عند لوقا وبولس. <s n=\"1.\">(<l>num igitur</l>) تتوقع جوابًا بالنفي، <r v=\"Luke.18.8\"></r>؛ <g>ἆρά γε</g>، <r v=\"Acts.8.30\"></r>.</s> <s n=\"2.\">(<l>ergone</l>) في جواب الشرط، تتوقع جوابًا بالإيجاب، <r v=\"Gal.2.17\"></r>.†</s>","en":"<f><o>ἆρα</o>,</f> interrog. particle, implying anxiety or impatience, \"quite rare and only in Luke and Paul, therefore a literary word\" (Bl., §77, 2). <s n=\"1.\">(<l>num igitur</l>) expecting a neg. reply, <r v=\"Luke.18.8\"></r>; <g>ἆρά γε</g>, <r v=\"Acts.8.30\"></r>.</s> <s n=\"2.\">(<l>ergone</l>) in apodosis, expecting an affirm. reply, <r v=\"Gal.2.17\"></r> (Bl., §77, 2; Lft., <i>Ga.</i>, in l.; MM, s.v.).†</s>"},"G674":{"l":"ἀποψύχω","o":1,"ar":"<f>** <o>ἀπο-ψύχω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية والسبعينية: <b>لفظ أنفاسه</b>، <b>أسلم الروح</b> (<r v=\"4Macc.15.18\"></r>).</s> <s n=\"2.\"><b>انقطع نفَسه</b>، <b>غُشي عليه</b>: يليه <g>ἀπό</g>، <r v=\"Luke.21.26\"></r>.†</s>","en":"<f>** <o>ἀπο-ψύχω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"4Macc.15.18\"></r>*;]</e> </et> <s n=\"1.\"><b>to breathe out life</b>, <b>expire</b> (Thuc.; LXX, <r v=\"4Macc.15.18\"></r>).</s> <s n=\"2.\"><b>to leave off breathing</b>, <b>faint</b> (Hom., <i>Od.</i>, xxiv, 348): seq. <g>ἀπό</g>, <r v=\"Luke.21.26\"></r>.†</s>"},"G643":{"l":"ἀποσκευάζω","o":null,"ar":"<f><o>ἀπο-σκευάζω</o>،</f> <s><b>حزم وحمل بعيدًا</b>؛ الصيغة الوسطى، <b>حزم أمتعته وارتحل</b>: <r v=\"Acts.21.15\"></r>، في النص المستلَم (انظر <g>ἐπισ-</g>).†</s>","en":"<f><o>ἀπο-σκευάζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.14.36\"></r> (<h n=\"H6437\">פּנה</h> pi.)*;]</e> </et> <s><b>to pack and carry off</b>; mid., <b>to pack and remove one's goods</b>: <r v=\"Acts.21.15\"></r>, Rec. (v. <g>ἐπισ-</g>).†</s>"},"G640":{"l":"ἀπορία","o":1,"ar":"<f><o>ἀπορία</o>، <g>-ας, ἡ</g></f> <s><b>حيرة</b>: <r v=\"Luke.21.25\"></r>.†</s>","en":"<f><o>ἀπορία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπορέω</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H928\">בֶּהָלָה</h>, etc.;]</e> </et> <s><b>perplexity</b>: <r v=\"Luke.21.25\"></r> (MM, s.v.; on the construction, v. Field, <i>Notes</i>, 74 f.).†</s>"},"G607":{"l":"ἀποκεφαλίζω","o":4,"ar":"<f>† <o>ἀπο-κεφαλίζω</o></f> <s><b>قطع الرأس</b>: <r v=\"Matt.14.10\"></r>، <r v=\"Mark.6.16\"></r>، <r v=\"Mark.6.28\"></r>، <r v=\"Luke.9.9\"></r>.†</s>","en":"<f>† <o>ἀπο-κεφαλίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπό</g></x>, <x><g>κεφαλή</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.151.7\"></r>*;]</e> </et> <s><b>to behead</b>: <r v=\"Matt.14.10\"></r>, <r v=\"Mark.6.16\"></r>, <r v=\"Mark.6.28\"></r>, <r v=\"Luke.9.9\"></r>.†</s>"},"G638":{"l":"ἀποπνίγω","o":2,"ar":"<f><o>ἀπο-πνίγω</o>،</f> <s><b>خنق</b>: <r v=\"Matt.13.7\"></r>، <r v=\"Luke.8.7\"></r>؛ المبني للمجهول، عن الغرق (= <x><g>καταποντίζομαι</g></x>)، <r v=\"Luke.8.33\"></r>.†</s>","en":"<f><o>ἀπο-πνίγω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Nah.2.12\"></r> (<r v=\"Nah.2.13\"></r>) (<h n=\"H2614\">חנק</h> pi.), <r v=\"Tob.3.8\"></r>*;]</e> </et> <s><b>to choke</b>: <r v=\"Matt.13.7\"></r>, <r v=\"Luke.8.7\"></r>; pass., of drowning (= <x><g>καταποντίζομαι</g></x>), <r v=\"Luke.8.33\"></r>.†</s>"},"G695":{"l":"ἀργυροκόπος","o":1,"ar":"<f>† <o>ἀργυροκόπος</o>، <g>-ου, ὁ</g></f> <s><b>صائغ فضة</b>: <r v=\"Acts.19.24\"></r>.†</s>","en":"<f>† <o>ἀργυροκόπος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἄργυρος</g></x>, <x><g>κόπτω</g></x>, <i>to beat</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Judg.17.4\"></r>, <r v=\"Jer.6.29\"></r> (<h n=\"H6884\">צֹרֵף</h>)*;]</e> </et> <s><b>a silversmith</b>: <r v=\"Acts.19.24\"></r> (Plut.; <g>π.</g>, v. MM, s.v.).†</s>"},"G633":{"l":"ἀπονίπτω","o":1,"ar":"<f><o>ἀπο-νίπτω</o>،</f> <s><b>غسل</b>: الصيغة الوسطى (انعكاسي)، <g>τ. χεῖρας</g>، <r v=\"Matt.27.24\"></r>.†</s>","en":"<f><o>ἀπο-νίπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7857\">שׁטף</h>, <h n=\"H7364\">רחץ</h>, <h n=\"H4229\">מחה</h>;]</e> </et> <s><b>to wash off</b>: mid. (reflex.), <g>τ. χεῖρας</g>, <r v=\"Matt.27.24\"></r>.†</s>"},"G634":{"l":"ἀποπίπτω","o":1,"ar":"<f><o>ἀπο-πίπτω</o>،</f> <s><b>سقط عن</b>: <r v=\"Acts.9.18\"></r>.†</s>","en":"<f><o>ἀπο-πίπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H4448\">מלל</h>, <h n=\"H5307\">נפל</h>, etc.;]</e> </et> <s><b>to fall off</b>: <r v=\"Acts.9.18\"></r>.†</s>"}});A.got[6]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});